// v50.23: HISTORY stood here — 13 snapshots, 24,929 value records, 1.79 MB of a 6.2 MB payload,
// parsed by every visitor on every load so the chart footnote could print a count and two dates.
// The snapshots now live in gn-history.js, which the pages do not load and package.py does not
// ship; update_calc_weekly.py appends to it there and verify_calc.py reads it there. The refresh
// rewrites the line below from the same snapshots, and the gate checks the two agree.
const GN_HISTORY_DATES = ["2026-06-12", "2026-06-15", "2026-06-17", "2026-06-20", "2026-06-21", "2026-06-22", "2026-07-20", "2026-07-27", "2026-07-28", "2026-08-10", "2026-08-17", "2026-08-24", "2026-09-06"];

const RAW_PER_DOLLAR = 527.08;
// v50.20: build constants the weekly script updates alongside RAW_PER_DOLLAR. Absorption is read from
// the methodology 13 month table on the data-through date, never hand-typed into the display code.
const GN_BUILD = 'v50.22';
  const GN_PACE_BASIS = 'rate';  // v50.22: pm compares rate to rate; see methodology 13;
const GN_DATA_THROUGH = '2026-09-06';
const GN_ABSORB_TABLE = {4:0.10, 5:0.20, 6:0.40, 7:0.60, 8:0.80, 9:0.90, 10:0.90};
const GN_ABSORB_MONTH = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][parseInt(GN_DATA_THROUGH.slice(5,7),10)-1];
const GN_ABSORB = GN_ABSORB_TABLE[parseInt(GN_DATA_THROUGH.slice(5,7),10)] || 0.90;
// CORE-6: the data week and the printable data date, derived once instead of typed into prose.
// The ROS mode line hardcoded "Wk 20" and kept saying it for three builds after the projection
// moved on (v50.22 build note: "GNROS described Week 20 in the last three builds; it describes
// Week 22 now"), while the footer said Week 22 and GN_DATA_THROUGH said 2026-09-06.
// GNDAILY.days is the scoring period the weekly script extends every run (152 -> 166 this
// build) and league scoring weeks have run 7 periods each since SP152/Aug 23 closed Week 20,
// so anchor there. Do NOT divide day 1 by 7: the short opening week and the All-Star break
// make 166/7 read 23.7, two weeks past the truth.
const GN_DATA_WEEK = 20 + Math.ceil((GNDAILY.days - 152) / 7);
const GN_DATA_THROUGH_TXT = GN_ABSORB_MONTH + ' ' + parseInt(GN_DATA_THROUGH.slice(8,10),10) + ', ' + GN_DATA_THROUGH.slice(0,4);
// Pre-peak production-basis Pure is a projected PEAK; pace is judged against this year's expectation (methodology 20.30 B).
function gnPaceExpectation(p){ const e=p.eng||{}; const pk=(p.p==='SP'||p.p==='RP')?27:26; if(p.a!=null&&p.a<pk&&e.b==='prod'&&e.g&&e.g>1) return p.pc/e.g; return p.pc; }
// v50.22 moved the pace multiplier to a rate-vs-rate basis (GN_PACE_BASIS==='rate').
// The engine records the inputs it used in each player's audit note; parse them so the
// Inspector and the decision spine can show the derivation that actually produced the
// stored multiplier instead of the retired counting-stat formula. Both rates are rounded
// to one decimal in the note, so .calc reproduces the stored pm only to about +/-0.01 --
// the stored pm is always what gets displayed as the result, and .pm (the note's own
// post-run figure, which matches the stored value exactly) is the staleness authority.
function gnPaceNote(p){
  const m=/PACE v50\.22 \(([^)]*)\): pm ([\d.]+) -> ([\d.]+); rate-based: (-?[\d.]+) vs (-?[\d.]+) per ([a-z ]+), w ([\d.]+)/.exec((p&&p.notes)||'');
  if(!m) return null;
  const rate=parseFloat(m[4]), exp=parseFloat(m[5]), w=parseFloat(m[7]);
  const ratio = exp ? rate/exp : null;
  const inner = (ratio!=null) ? 1 + w*(ratio-1) : null;
  const raw   = (inner!=null) ? 1 + GN_ABSORB*(inner-1) : null;
  return { asOf:m[1], prev:parseFloat(m[2]), pm:parseFloat(m[3]), rate:rate, exp:exp,
           unit:m[6], w:w, ratio:ratio, inner:inner, raw:raw,
           calc:(raw!=null)?Math.max(0.50,Math.min(1.50,raw)):null,
           clamped:(raw!=null)&&(raw<0.50||raw>1.50) };
}
function gnPmAllowed(p){ return p.t==='T1'||p.t==='T2'||(p.t==='T3'&&p.ph==='Established'); }
let MODE = 'ra';
let BLEND = 0;
let YEARS = 1;
let YEAR_MODE = 'cumulative';  // 'cumulative' or 'single'
let FADE_MODE = 'off';  // 'on' or 'off' — T3/T4 bust risk fade-in


const state = { A: [], B: [] };
const $ = (id) => document.getElementById(id);
const orgList = [...new Set(PLAYERS.map(p => p.o))].sort();
const posList = [...new Set(PLAYERS.map(p => p.p).filter(Boolean))].sort();
// v50.23: one pass over PLAYERS, built once, instead of filtering all 2,118 rows by org at five
// call sites. renderMgrChart maps eight orgs and the roster helpers it calls re-scanned the
// same org again: 16,944 comparisons a render, 33,888 at the levels that scan twice.
// PLAYERS never changes after load. The arrays are SHARED: every caller copies before it
// sorts (filter / slice / gnRankBy all copy) and must keep doing so.
const PLAYERS_BY_ORG = (() => {
  const m = new Map();
  for (const p of PLAYERS) { const k = p.o || ''; let a = m.get(k); if (!a) { a = []; m.set(k, a); } a.push(p); }
  return m;
})();
function playersOf(org) { return PLAYERS_BY_ORG.get(org) || []; }
// Decorate-sort-undecorate, descending. The comparator form called the value function twice
// per comparison: 466 getKval calls to rank one 52-man roster, 3,554 across the eight orgs one
// manager render builds. renderResults already did this (CORE-4); ten sort sites were missed.
// Returns a NEW array. Array.prototype.sort is stable, so ties keep input order exactly as
// the comparator form did, and null keys subtract exactly as they did (CORE-2 is unchanged).
function gnRankBy(arr, keyFn) {
  const rows = arr.map(p => ({ p: p, k: keyFn(p) }));
  rows.sort((a, b) => b.k - a.k);
  return rows.map(r => r.p);
}
(function(){var _pc=document.getElementById("playerCount");if(_pc)_pc.textContent=PLAYERS.length.toLocaleString();})();

// SL-6: the Pure end of the single-year blend. r already carries the pace multiplier (r = pc x h x
// pm, exact for every one of the 96 players this inverted) and so do BOTH engine trajectories (tj
// and tjp: median ratio to pc x h x pm and to pc x pm is 0.953 either way). The bare ceiling here
// was the only pace-free number in the blend, which is why sliding toward "Pure" LOWERED 96
// players (Ohtani 2010 -> 1769, Aranda 966 -> 722). gnReleaseCap already applies pm to the ceiling
// the same way. The "Pure NNNN" badges keep showing the stored ceiling field.
function gnPure(p) { return (p.pc || 0) * (p.pm || 1); }
// Single-year blended raw value
function blendedRaw(p) {
  const b = BLEND / 100;
  return (1 - b) * p.r + b * gnPure(p);
}

// Career value: sum trajectory for first N years
// At YEARS=1, use blended single-year value (so blend slider still works)
// At YEARS>1, blend the engine's RA trajectory (tj) with its Pure trajectory (tjp) year by year

// Healthy base lookup by age + role (matches engine.py)
function healthyBaseJS(age, role) {
  if (role === 'SP') {
    if (age <= 28) return 0.94;
    if (age <= 31) return 0.91;
    if (age <= 34) return 0.88;
    if (age <= 36) return 0.85;
    return 0.82;
  }
  if (role === 'RP') {
    if (age <= 28) return 0.92;
    if (age <= 31) return 0.91;
    if (age <= 34) return 0.88;
    return 0.85;
  }
  // Hitter
  if (age <= 28) return 0.96;
  if (age <= 31) return 0.94;
  if (age <= 34) return 0.92;
  if (age <= 36) return 0.88;
  return 0.85;
}

// When FADE_MODE is on, T3/T4 players get their bust discount linearly faded out
// from year 1 (full discount) to peak age (full healthy_base, no rookie penalty).
function prospectBlend(player) {
  const e = player.eng || {};
  if (e.bdisc != null) return e.bdisc;
  const m = (player.notes || '').match(/blend\s+(\d+)\/(\d+)\/(\d+)/);
  if (m) { const a=+m[1], b=+m[2], c=+m[3]; return Math.round((a/100*1.0 + b/100*0.60 + c/100*0.0)*1000)/1000; }
  return 1.0;
}

// ---- promotion ladder (methodology 9 + 11 + 14) -----------------------------
// Commissioner ruling, Aug 25 2026: the Ceiling-Fade switch releases ALL THREE prospect
// suppressors - the scouting bust, the maturation discount, and the level-proximity penalty -
// on the schedule the player would actually climb, one level per season, rather than on a
// straight line to peak age. Year 1 A-ball, year 2 AA, year 3 AAA, year 4 MLB rookie; the
// section 14 growth ramp carries him from there to his peak year.
const GN_LADDER = ['A-or-below','AA','AAA','MLB Honeymoon','MLB Book','Established'];
const GN_MATUR_AT = {'A-or-below':0.30,'AA':0.40,'AAA':0.50,'MLB Honeymoon':0.60,'MLB Book':0.80,'Established':1.00};
function gnProxAt(stage, isPitcher){        // methodology 11 level-proximity bands (AAA and MLB share one bucket)
  if (stage === 'A-or-below') return isPitcher ? 0.20 : 0.15;
  if (stage === 'AA')  return isPitcher ?  0.00 : -0.05;
  return isPitcher ? -0.05 : -0.10;          // AAA, MLB Honeymoon, MLB Book, Established: the credit is kept once earned
}
function gnStageIdx(player){
  const e = player.eng || {};
  const i = GN_LADDER.indexOf(e.maturst);
  if (i >= 0) return i;
  if (player.ph === 'Honeymoon')   return 3; // no stored stage: fall back to MLB phase
  if (player.ph === 'Book')        return 4;
  if (player.ph === 'Established') return 5;
  return -1;                                 // unknown: use the original straight-line fade
}
// ---- v50.22 FIX 2: the ceiling is the authority on its own discounts -------
// prospectBlend() reads a "blend a/b/c" line out of the notes field. notes is an APPEND-ONLY
// log: a later GL REBUILD / DERISK pass replaces the ceiling outright but does not delete the
// earlier blend line, so the regex can still find a factor that is no longer in the ceiling.
// Dividing by it over-releases the player - up to 1.85x (Travis Sykora, whose released Pure
// reached 2866 against a true ceiling of 1548). eng.tc, eng.matur and eng.sc pin down what the
// ceiling really contains, so test it instead of trusting the prose.
function blendInCeiling(player) {
  const e = player.eng || {};
  const bd = prospectBlend(player);
  if (bd >= 0.999) return 1.0;                     // nothing to divide out
  const tc = e.tc;
  if (!tc || !player.pc) return bd;                // cannot test: keep prior behaviour
  const mat = (e.matur != null && e.matur < 1) ? e.matur : 1.0;
  const sc  = (e.sc != null) ? e.sc : 1.0;
  const tol = Math.max(1, 0.01 * player.pc);
  if (Math.abs(tc * mat * sc - player.pc)      <= tol) return 1.0;   // blend ABSENT
  if (Math.abs(tc * mat * sc * bd - player.pc) <= tol) return bd;    // blend PRESENT
  return bd;                                       // neither reconciles: prior behaviour
}

// The most a release may ever reach, in the units tjp is stored in:
//     max(pc, eng.tc x eng.sc) x pm
// eng.tc x eng.sc is the ceiling a fully matured prospect is scouted to reach. pc is a FLOOR on
// the cap, because it sits above eng.tc for 15 players whose 19.6 ratchet banked production past
// the scouting grade, and releasing risk must never subtract value. The x pm is required because
// tjp is stored pace-ADJUSTED rather than as raw Pure - on the v50.21 board max(tjp) == pc x pm
// for all 373 players carrying a multiplier off 1.00 - so the cap must live in the same units as
// the quantity it bounds. Returns null when eng.tc is absent, asserting no cap.
function gnReleaseCap(player) {
  const e = player.eng || {};
  const tc = e.tc;
  if (!tc || !player.pc) return null;
  const sc = (e.sc != null) ? e.sc : 1.0;
  const pm = player.pm ? player.pm : 1.0;
  return Math.max(player.pc, tc * sc) * pm;
}

function fadeAdjustedTj(player, yearIdx) {
  const type = String(player.t || '');
  if (FADE_MODE === 'off' || (type !== 'T3' && type !== 'T4')) {
    return (player.tj && player.tj[yearIdx]) || 0;
  }
  if (!player.tjp || player.tjp[yearIdx] === undefined) {
    return (player.tj && player.tj[yearIdx]) || 0;
  }
  const role = player.p === 'SP' ? 'SP' : (player.p === 'RP' ? 'RP' : 'H');
  const isPitcher = role === 'SP' || role === 'RP';
  const peakAge = isPitcher ? 27 : 26;
  const currentAge = player.a || 25;
  const yearAge = currentAge + yearIdx;
  const currentHit = player.h || 0.80;
  const e = player.eng || {};
  const bd  = blendInCeiling(player);      // v50.22 FIX 2: was prospectBlend(player)
  const mat = (e.matur != null && e.matur < 1) ? e.matur : 1.0;
  const s0  = gnStageIdx(player);
  const yearsToPeak = peakAge - currentAge;
  // Two clocks govern how fast a prospect's risk is spent, and the slower one binds.
  //   ladder clock - one level per season, from where he is now to Established.
  //   peak clock   - the scouting bust is not spent on arrival in the majors, it is spent when
  //                  he becomes what he was scouted to be, i.e. his peak / T1 year.
  // A 20-year-old in A-ball is ladder-limited early and peak-limited late; a 26-year-old still
  // in A-ball is ladder-limited throughout, which is the correct read on him.
  const last = GN_LADDER.length - 1;
  const sk = (s0 >= 0) ? Math.min(s0 + yearIdx, last) : -1;
  const ladderF = (s0 < 0 || s0 >= last) ? 1 : (sk - s0) / (last - s0);
  const peakF = (yearIdx === 0) ? 0
              : (yearsToPeak <= 0 ? 1 : Math.min(1, yearIdx / yearsToPeak));
  const fraction = Math.min(peakF, ladderF);
  let hit, matFaded;
  if (s0 >= 0) {
    matFaded = Math.max(mat, GN_MATUR_AT[GN_LADDER[sk]]);   // discrete, one level per season
  } else {
    matFaded = mat + (1 - mat) * fraction;
  }
  if (s0 >= 0 && e.mb != null) {
    // total scouting bust = matrix bust + level proximity (methodology 11); the stored
    // eng.buste carries the matrix term only, so proximity is added here explicitly.
    const prox0 = (e.prox != null) ? e.prox : 0;
    const phf   = (e.phf  != null) ? e.phf  : 1;
    const base  = (e.base != null) ? e.base : 0.96;
    const proxK  = (sk === s0) ? prox0 : Math.min(prox0, gnProxAt(GN_LADDER[sk], isPitcher));   // v50.20: a promotion never withdraws proximity credit
    const busteK = Math.min(Math.max(0, e.mb * (1 - fraction) + proxK) * phf, 0.95);
    const buste0 = Math.min(Math.max(0, e.mb + prox0) * phf, 0.95);
    // move only the bust component of Hit%: durability, IL stack and outlier terms are
    // permanent and are not released by a promotion
    hit = Math.min(0.96, Math.max(0.20, currentHit + base * (buste0 - busteK)));
  } else {
    // no bust on file: ease toward the age/role healthy base, but never below where the
    // risk-adjusted view already has him - releasing risk must not subtract value
    const target = Math.max(currentHit, healthyBaseJS(yearAge, role));
    hit = currentHit + (target - currentHit) * fraction;
  }
  const bdFaded = bd + (1 - bd) * fraction;
  let fadedPure = (player.tjp[yearIdx] / bd / mat) * bdFaded * matFaded;
  const relCap = gnReleaseCap(player);   // v50.22 FIX 2: hard release cap
  if (relCap != null && fadedPure > relCap) fadedPure = relCap;
  return fadedPure * hit;
}

function getValue(p) {
  let raw;
  const b = BLEND / 100;
  if (YEARS === 1) {
    // Year 1 always = blended peak/current value regardless of cumulative vs single
    raw = blendedRaw(p);
  } else if (YEAR_MODE === 'single') {
    const idx = YEARS - 1;
    if (p.tj && p.tjp && p.tj.length > idx && p.tjp.length > idx) {
      const tjVal = fadeAdjustedTj(p, idx);
      const tjpVal = p.tjp[idx];
      // SL-7: a pre-arrival year is one where the trajectory is still OFF and turns ON later. The
      // old test (both trajectories under 5, ceiling above 0) could not tell that from a trajectory
      // that has already run OUT: at year 10 it fired for 178 players, 128 of them T1/T2 veterans
      // aged 30+, and not one true pre-arrival case exists in this build (no trajectory starts at
      // zero and turns on later). Mike Trout at year 10, age 44, read 795 -- his full current
      // value -- off a trajectory of 2, and doubled between year 9 and year 10.
      const laterOn = p.tj.slice(idx + 1).some(v => v >= 5) || p.tjp.slice(idx + 1).some(v => v >= 5);
      const isPreArrival = (tjVal < 5 && tjpVal < 5 && p.pc > 0 && laterOn);
      if (isPreArrival) {
        // full peak value -- the prospect's option value while still developing
        raw = (1 - b) * p.r + b * gnPure(p);
      } else {
        // SL-8: the flat half-of-current floor is gone. On this build it never bound for a player
        // aged 31 or younger in the year shown, and only bound once his own trajectory had fallen
        // below half of its year-1 value: it propped up decline-tail years (1,124 of 2,078 players
        // at year 10, 233 of them by 5x or more) and nothing else. The trajectories already carry
        // the pace multiplier, so there is no pace gap for a floor to cover.
        raw = (1 - b) * tjVal + b * tjpVal;
      }
    } else {
      raw = blendedRaw(p);
    }
  } else {
    if (p.tj && p.tjp && p.tj.length >= YEARS && p.tjp.length >= YEARS) {
      let trajSum = 0;
      for (let i = 0; i < YEARS; i++) {
        trajSum += (1 - b) * fadeAdjustedTj(p, i) + b * p.tjp[i];
      }
      const floor = (1 - b) * p.r + b * gnPure(p);
      raw = Math.max(trajSum, floor);
    } else if (p.tj && p.tj.length >= YEARS) {
      const trajSum = p.tj.slice(0, YEARS).reduce((s, v) => s + v, 0);
      raw = Math.max(trajSum, p.r);
    } else {
      raw = p.r * YEARS;
    }
  }
  if (MODE === 'dollar') return raw / RAW_PER_DOLLAR;
  return raw;
}

function fmtValue(v) {
  if (MODE === 'dollar') return '$' + v.toFixed(2);
  // SA-8: the side totals printed 17110 beside a manager panel printing 17,110
  return Math.round(v).toLocaleString();
}

// SA-4: the org menu was the raw org strings -- 49 entries, 41 of them free-agent variants, with no
// way to see all 1,709 free agents at once ("FA" alone is 504 of them) and two MLB clubs spelled two
// ways in the pull (CWS/CHW, WAS/WSH). Grouped now: league teams, one all-free-agents entry, then FA
// by MLB club with the duplicate spellings folded onto the dominant one, then the dropped-by-a-team
// entries. The alias lives here and in gnOrgMatch only; the records keep the spelling they came with.
const GN_ORG_ALIAS = { 'FA (CHW)': 'FA (CWS)', 'FA (WAS)': 'FA (WSH)' };
function gnOrgKey(o) { o = (o || '') + ''; return GN_ORG_ALIAS[o] || o; }
function gnOrgMatch(p, org) {
  const o = (p.o || '') + '';
  if (org === '__FA__') return o.indexOf('FA') === 0;
  return gnOrgKey(o) === org;
}
function populateFilters() {
  const keys = [...new Set(PLAYERS.map(p => gnOrgKey(p.o)))].sort();
  const teams = keys.filter(o => o.indexOf('FA') !== 0);
  const faClub = (keys.indexOf('FA') !== -1 ? ['FA'] : []).concat(keys.filter(o => /^FA \((?!was )/.test(o)));
  const faWas = keys.filter(o => o.indexOf('FA (was ') === 0);
  const faAll = PLAYERS.filter(p => ((p.o || '') + '').indexOf('FA') === 0).length;
  ['orgA','orgB'].forEach(id => {
    const sel = $(id);
    const group = (label, list, text) => {
      if (!list.length) return;
      const g = document.createElement('optgroup'); g.label = label;
      list.forEach(o => { const opt = document.createElement('option'); opt.value = o; opt.textContent = text ? text(o) : o; g.appendChild(opt); });
      sel.appendChild(g);
    };
    group('League teams', teams);
    const fa = document.createElement('option'); fa.value = '__FA__'; fa.textContent = 'All free agents (' + faAll.toLocaleString() + ')'; sel.appendChild(fa);
    group('Free agents by MLB club', faClub, o => o === 'FA' ? 'FA — no club listed' : o.replace(/^FA \((.*)\)$/, 'FA — $1'));
    group('Dropped by a league team', faWas, o => o.replace(/^FA \(was (.*)\)$/, 'FA — was $1'));
  });
  ['posA','posB'].forEach(id => {
    const sel = $(id);
    posList.forEach(p => { const opt = document.createElement('option'); opt.value = p; opt.textContent = p; sel.appendChild(opt); });
  });
}
populateFilters();

function getOrgBadge(o) {
  if (o === 'C-Town Liquors') return 'C-Town Liquors';
  if (o.startsWith('FA')) return o.replace('FA ','').replace(/[()]/g,'') || 'FA';
  return o.slice(0, 3).toUpperCase();
}
function rosterBadge(p) {
  if (!p) return '';
  const o = (p.o || '').toString();
  if (o.startsWith('FA')) return o.replace('FA','').replace(/[()]/g,'').trim() || 'FA';
  return p.rn || o;
}

// INSP-6: search folded nothing. Every box tested a raw substring against the
// un-normalised name, so "pedro ramirez" could not reach Pedro Ramírez -- 24 of the 2,118
// shipped names carry diacritics and were unreachable by their ASCII spelling. Fold BOTH
// sides: NFD splits the accent off as a combining mark (U+0300-U+036F) and the strip drops
// it. Every accented character in the data (a/e/i/n/o/u with acute or tilde) decomposes.
// normalize() is the costly half, so the per-name result is memoised -- the 2,118 names
// fold once each on the first keystroke and every keystroke after that folds only the query.
const _GN_FOLD = Object.create(null);
// review: the cache below is keyed by every string ever folded. Names are bounded at 2,118;
// QUERIES are not -- four search boxes, one new key per keystroke, never evicted. Memoise the
// names (the hot path: every name is folded on every keystroke) and let queries fold and go.
const _GN_NAMES = new Set(PLAYERS.map(p => p.n));
function gnFold(s) {
  s = (s == null) ? '' : String(s);
  let f = _GN_FOLD[s];
  // SA-7: fold punctuation as well as accents. Apostrophes and periods drop out ("ohearn" reaches
  // O'Hearn, "guerrero jr" reaches Guerrero Jr.), hyphens become spaces ("encarnacion strand" reaches
  // Encarnacion-Strand) and runs of space collapse. 8 names carry an apostrophe and 23 a hyphen.
  if (f === undefined) f = s.normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[’'.]/g, '').replace(/-/g, ' ').replace(/\s+/g, ' ').trim();
  if (f !== undefined && _GN_NAMES.has(s)) _GN_FOLD[s] = f;
  return f;
}

// SL-1: the slider and toggle handlers re-rendered BOTH results lists on every tick, and
// renderResults adds the open class whenever a query or filter is set -- so a list the user had
// closed came back (61 rows over the Side A card) on an arrow key, and flashed open during a
// mouse drag until the release click closed it again. A closed list is rebuilt the next time its
// input is focused, so refreshing only the open ones loses nothing.
// SA-8: identity for the "already picked" checks -- the ESPN id when the record has one, name+org
// otherwise. They compared bare names, which is safe on this build (no two records share one) but
// would hide two different players behind each other the first time it happened.
function gnPKey(p) { return p.eid != null ? 'e' + p.eid : (p.n + '|' + (p.o || '')); }
function gnSideOf(p) {
  const k = gnPKey(p);
  if (state.A.some(x => gnPKey(x) === k)) return 'A';
  if (state.B.some(x => gnPKey(x) === k)) return 'B';
  return null;
}
function gnRefreshOpenResults() {
  ['A','B'].forEach(s => { const box = $('results' + s); if (box && box.classList.contains('open')) renderResults(s); });
}
function renderResults(side) {
  const q = gnFold($('search'+side).value.trim());
  const org = $('org'+side).value;
  const pos = $('pos'+side).value;
  const sort = $('sort'+side).value;
  const box = $('results'+side);
  const CAP = 60;   // v50.22 CORE-4: the row cap now lives in two slice paths; keep them one number
  if (!q && !org && !pos) { box.classList.remove('open'); box.innerHTML=''; return; }
  // SA-7: every typed word must appear somewhere in the folded name, so "rodriguez julio" finds
  // Julio Rodriguez. SA-4: the org value may be the grouped all-free-agents token or an aliased club.
  const qTokens = q ? q.split(' ') : [];
  const matches = p => {
    if (qTokens.length) { const fn = gnFold(p.n); for (const t of qTokens) if (fn.indexOf(t) === -1) return false; }
    if (org && !gnOrgMatch(p, org)) return false;
    if (pos && p.p !== pos) return false;
    return true;
  };
  // v50.20: a player can only be received once. SA-5: the ones this hides are kept, so an empty list
  // can say where the player went instead of "No matches".
  const held = [];
  let list = PLAYERS.filter(p => {
    if (!matches(p)) return false;
    const on = gnSideOf(p);
    if (on) { held.push({ p: p, side: on }); return false; }
    return true;
  });
  const total = list.length;
  // v50.22 CORE-4: getValue is expensive at the far end of the sliders - at YEARS=10 it runs
  // fadeAdjustedTj ten times per player, and the bust-risk-off view sends every one of those
  // through prospectBlend's notes regex. The old comparator called getValue TWICE per comparison
  // over the whole match set and then the slice threw all but 60 rows away: a 1,692-name search
  // burned 30,576 calls / 52 ms to paint 60 rows, and 15.8 ms per slider-input tick even at the
  // narrower pos=SP with both sides redrawing. Value each player ONCE into a keyed array, sort on
  // the key, and paint from that same number - a Schwartzian transform. 1,692 calls, 3.5 ms.
  // The comparator sees identical numbers in the identical order, so the sort ORDER is unchanged.
  let rows;
  if (sort === 'value') {
    rows = list.map(p => ({ p: p, v: getValue(p) }));
    rows.sort((a,b) => b.v - a.v);
    rows = rows.slice(0, CAP);
  } else {
    // name and age sort on fields that cost nothing to read, so slice FIRST and value only the 60
    // rows that survive. Decorating the whole list here would have taken these two from 60 calls
    // to 1,692 - applying the transform uniformly makes the cheap sorts 5x SLOWER, not faster.
    if (sort === 'name') list.sort((a,b) => a.n.localeCompare(b.n));
    else if (sort === 'age') list.sort((a,b) => (a.a||999) - (b.a||999));
    rows = list.slice(0, CAP).map(p => ({ p: p, v: getValue(p) }));
  }
  box.innerHTML = rows.map(r =>
    '<div class="result-item" data-n="' + _iesc(r.p.n) + '" data-o="' + _iesc(r.p.o) + '">' +
      '<div><div>' + _iesc(r.p.n) + '</div><div class="meta">' + _iesc(r.p.p) + ' | age ' + (r.p.a||'-') + ' | ' + _iesc(rosterBadge(r.p)) + ' | ' + _iesc(r.p.t) + (r.p.ph ? ' ' + _iesc(r.p.ph) : '') + '</div></div>' +
      '<div class="ra">' + fmtValue(r.v) + '</div>' +
    '</div>'
  ).join('') || (held.length
    // SA-5: a searched player who already sits on a side read as "No matches", as if he did not exist
    ? held.slice(0, 3).map(h => '<div class="result-item meta" role="presentation" style="cursor:default;">' + _iesc(h.p.n) + ' is already on Side ' + h.side + '</div>').join('')
    : '<div class="result-item meta" role="presentation" style="cursor:default;">No matches</div>');
  // v50.22 CORE-3: the cap is 60 and the 60th row used to be just another player, with nothing
  // saying the other 441 existed. Under Sort: Value those 60 really are the top 60; under
  // Sort: Name they are Aaron Civale through Briggs McKenzie and the rest of the alphabet is
  // invisible. total was captured before the slice, so saying which 60 these are costs nothing.
  // insertAdjacentHTML rather than re-reading box.innerHTML: reading it back would round-trip
  // 60 rows through the parser and serializer. The note carries no data-n, so it stays out of
  // the click wiring below and out of rows()/stamp() in the arrow-key block.
  if (total > rows.length) {
    const kept = sort === 'value' ? 'Top ' + rows.length + ' by value'
               : sort === 'name'  ? 'First ' + rows.length + ' A-Z'
               : sort === 'age'   ? 'Youngest ' + rows.length
               :                    'First ' + rows.length;
    box.insertAdjacentHTML('afterbegin', '<div class="result-item meta" role="presentation" style="cursor:default;">' +
      kept + ' of ' + total + ' matches · narrow the search to see the rest</div>');
  }
  box.classList.add('open');
  [...box.querySelectorAll('.result-item[data-n]')].forEach(el => {
    el.addEventListener('click', () => {
      const player = PLAYERS.find(p => p.n === el.dataset.n && p.o === el.dataset.o);
      if (player) addPlayer(side, player);
    });
  });
}

function addPlayer(side, player) {
  state[side].push(player);
  $('search'+side).value = '';
  $('results'+side).classList.remove('open');
  $('results'+side).innerHTML = '';
  renderPicked(side);
  renderVerdict();
  gnSaveState();
  gnAnnounce(player.n + ' added to Side ' + side + '. Side ' + side + ' total ' + $('total'+side).textContent + '.');
}
// v50.20: persist only identity keys; the full player object used to be stored and then restored verbatim,
// so after every weekly refresh a returning user saw last week's values until they pressed Clear.
function gnSaveState(){
  try { localStorage.setItem('gn-trade-state', JSON.stringify({ A: state.A.map(p => ({n:p.n, eid:p.eid})), B: state.B.map(p => ({n:p.n, eid:p.eid})) })); } catch(e) {}
}
function gnResolveSaved(arr){
  const out = []; const seen = new Set();
  (Array.isArray(arr) ? arr : []).forEach(s => {
    if (!s) return;
    const live = PLAYERS.find(p => (s.eid != null && p.eid === s.eid)) || PLAYERS.find(p => p.n === s.n);
    if (live && !seen.has(gnPKey(live))) { seen.add(gnPKey(live)); out.push(live); }
  });
  return out;
}

// SA-6: a visually hidden polite live region. Nothing on the page announced an add or a removal;
// the total changed silently. Cleared and refilled a tick later so a repeated message re-announces.
function gnAnnounce(msg) { const el = $('gnStatus'); if (!el) return; el.textContent = ''; setTimeout(() => { el.textContent = msg; }, 30); }
function removePlayer(side, idx, viaKeyboard) {
  const gone = state[side][idx];
  state[side].splice(idx, 1);
  renderPicked(side);
  renderVerdict();
  gnSaveState();
  if (gone) gnAnnounce(gone.n + ' removed from Side ' + side + '. Side ' + side + ' total ' + $('total'+side).textContent + '.');
  // SA-3: renderPicked rebuilt the list, so the button that had focus is gone and focus fell to
  // <body>; a keyboard user lost their place after every removal. Land on the button now in the same
  // slot (or the last one) and, with the side empty, on its search box -- keyboard removals only, so
  // a tap on a phone does not raise the keyboard. Focus that survived (Safari leaves it in the text
  // box on a mouse click) is left alone.
  if (document.activeElement && document.activeElement !== document.body) return;
  const btns = $('picked'+side).querySelectorAll('.remove-btn');
  if (btns.length) btns[Math.min(idx, btns.length - 1)].focus();
  else if (viaKeyboard) $('search'+side).focus();
}

function renderPicked(side) {
  const box = $('picked'+side);
  if (state[side].length === 0) { box.innerHTML = '<div class="empty-hint">No players selected</div>'; return; }
  box.innerHTML = state[side].map((p, i) =>
    '<div class="player-row" data-o="' + _iesc((p.o||'')+'') + '">' +
      '<div><div class="name">' + _iesc(p.n) + '</div>' +
        '<div class="meta">' + _iesc(p.p) + ' | age ' + (p.a||'-') + ' | ' + _iesc(p.t) + (p.ph ? ' ' + _iesc(p.ph) : '') + ' | Pure ' + Math.round(p.pc) + ' | Hit% ' + (p.h ? (p.h*100).toFixed(0) + '%' : '-') + '</div>' +
      '</div>' +
      '<div class="meta roster" title="' + _iesc(rosterBadge(p)) + '">' + _iesc(rosterBadge(p)) + '</div>' +
      '<div class="ra">' + fmtValue(getValue(p)) + '</div>' +
      '<button class="remove-btn" data-side="' + side + '" data-i="' + i + '" aria-label="Remove ' + _iesc(p.n) + ' from Side ' + side + '">x</button>' +
    '</div>'
  ).join('');
  [...box.querySelectorAll('.remove-btn')].forEach(btn => {
    btn.addEventListener('click', (e) => removePlayer(btn.dataset.side, parseInt(btn.dataset.i, 10), e.detail === 0));
  });
}

// V-2: the box printed rounded totals but graded the exact sums, so two sides shown as 62 and 62
// carried a verdict line reading "Side A +0 (0.1%)". Round ONCE, to the precision the mode prints,
// and let every number below come from that -- displayed totals, the gap, the percentage, the tag.
function gnDisplayRound(v) { return MODE === 'dollar' ? Math.round(v * 100) / 100 : Math.round(v); }
// V-1: grading was percentage-only, so two waiver-fodder free agents worth 2 and 1 scored
// "Side A wins big" off a one-point gap. A verdict needs an absolute floor as well as a ratio.
// The floor is FIVE CENTS of value, carried across the modes by the build's own anchor:
// $1 = RAW_PER_DOLLAR RA. Measured on this build, five cents is 26 RA -- under it sit 147 of the
// 2,118 board records and NONE of the 409 rostered players, whose 5th percentile is 368 RA. ROS
// projections are fantasy points with no dollar anchor, but the board is bimodal there: 44 players
// under 5 FP, then nothing at all until 180. Any floor inside that empty band behaves identically.
function gnFloor() {
  if (MODE === 'ros') return 10;                 // projected FP, inside the 5-to-180 gap
  if (MODE === 'dollar') return 0.05;            // five cents, as the mode prints it
  return 0.05 * RAW_PER_DOLLAR;                  // the same five cents in RA
}
function gnFloorText() {
  if (MODE === 'ros') return '10 projected FP';
  if (MODE === 'dollar') return '$0.05';
  return '$0.05 (' + Math.round(gnFloor()) + ' RA)';
}
function renderVerdict() {
  // CORE-2: in ROS mode getValue returns null for a player the projection does not cover --
  // 899 of the 2,118 board records. Summing those as 0 understated whichever side held them,
  // which is how a deal with an unprojected player on it scored "Fair trade". An unprojected
  // man can only ADD to his side, so a side that holds one shows a FLOOR, marked with >=.
  const vA = state.A.map(p => getValue(p));
  const vB = state.B.map(p => getValue(p));
  const unA = vA.filter(v => v === null).length;
  const unB = vB.filter(v => v === null).length;
  const un = unA + unB;
  const sumA = gnDisplayRound(vA.reduce((s,v) => s + (v || 0), 0));
  const sumB = gnDisplayRound(vB.reduce((s,v) => s + (v || 0), 0));
  const floorA = unA ? '≥ ' : '', floorB = unB ? '≥ ' : '';
  $('totalA').textContent = floorA + fmtValue(sumA);
  $('totalB').textContent = floorB + fmtValue(sumB);
  $('vTotalA').textContent = floorA + fmtValue(sumA);
  $('vTotalB').textContent = floorB + fmtValue(sumB);
  // V-8: the 5% and 15% cutoffs lived only in the source, and nothing said what the percentage
  // was a percentage OF. The legend under the box carries the rule now; this repeats it in reach
  // of a pointer, and names the floor in the units the current mode prints.
  $('vTag').title = 'The percentage is of the larger side. Under 5% is fair, 5 to 15% a slight edge, '
    + 'above 15% a clear win. A gap under ' + gnFloorText() + ' is called even rather than graded.';
  if (state.A.length === 0 && state.B.length === 0) {
    $('vTag').textContent = 'Pick players';
    $('vTag').className = 'verdict-tag tag-empty';
    $('vDelta').textContent = '-';
    return;
  }
  // V-4/V-5/V-6: one side empty is a half-built proposal, not a trade. It used to grade as
  // "Side A wins big (100.0%)"; with a zero-value player on the full side it claimed "Both sides
  // total 0" naming a side that held nobody; and in ROS mode a lone unprojected player against an
  // empty side printed "No verdict" when that side can only be ahead.
  if (state.A.length === 0 || state.B.length === 0) {
    const empty = state.A.length === 0 ? 'A' : 'B';
    $('vTag').textContent = 'One-sided';
    $('vTag').className = 'verdict-tag tag-empty';
    $('vDelta').textContent = 'Side ' + empty + ' receives nothing yet';
    return;
  }
  const diff = sumA - sumB;
  const bigger = Math.max(sumA, sumB);
  const absDiff = Math.abs(diff);
  const FLOOR = gnFloor();
  if (un > 0) {
    // A direction is safe only when the side that TRAILS is fully projected: then the margin
    // shown is a floor and can only grow. Fairness never is -- the missing man could be worth
    // 500 FP -- so this path cannot reach tag-fair, which was the wrong answer being printed.
    // V-1: a floor margin under the materiality floor is not a lead worth naming either
    const ahead = (unB === 0 && diff >= FLOOR) ? 'Side A' : ((unA === 0 && -diff >= FLOOR) ? 'Side B' : null);
    $('vTag').textContent = ahead ? (ahead + ' ahead, at least') : 'No verdict';
    $('vTag').className = 'verdict-tag ' + (ahead ? 'tag-slight' : 'tag-empty');
    $('vDelta').textContent = ahead
      ? (ahead + ' +' + fmtValue(absDiff) + ' or more (' + un + ' unprojected)')
      : (un + (un === 1 ? ' player has' : ' players have') + ' no ROS projection');
    return;
  }
  if (bigger === 0) {
    // Every player on both sides is projected, and projected at 0 (ROS: farm stashes and
    // form <= 0 under the idle gate; RA/dollar: the 38 records with r and pc both 0). pct is
    // 0 by construction there, so the old grading printed a green "Fair trade" off two empty
    // columns -- an equal split of nothing is not a fair trade, it is no information.
    $('vTag').textContent = 'No value either side';
    $('vTag').className = 'verdict-tag tag-empty';
    $('vDelta').textContent = 'Both sides total 0';
    return;
  }
  // V-1: both sides are noise. Ratios are meaningless here -- 2 against 1 is a 50% edge and also
  // nothing at all -- so say that instead of grading it.
  if (bigger < FLOOR) {
    $('vTag').textContent = 'Negligible value';
    $('vTag').className = 'verdict-tag tag-empty';
    $('vDelta').textContent = 'Both sides under ' + gnFloorText();
    return;
  }
  const winner = diff > 0 ? 'Side A' : 'Side B';
  // V-1: a real gap has to clear the floor in absolute terms before a ratio can call it an edge.
  if (absDiff < FLOOR) {
    $('vTag').textContent = 'Fair trade';
    $('vTag').className = 'verdict-tag tag-fair';
    $('vDelta').textContent = diff === 0 ? 'Even' : 'Within ' + gnFloorText() + ' — too close to call';
    return;
  }
  // V-3: the cutoffs used to test the exact percentage while the line printed it rounded, so a true
  // 4.95% displayed "5.0%" and graded Fair, and a true 14.97% displayed "15.0%" and graded a slight
  // edge. Round once, then grade the number the reader is looking at.
  const pct = Math.round(absDiff / bigger * 1000) / 10;
  $('vDelta').textContent = winner + ' +' + fmtValue(absDiff) + ' (' + pct.toFixed(1) + '%)';
  let cls, tag;
  if (pct < 5) { cls = 'tag-fair'; tag = 'Fair trade'; }
  else if (pct < 15) { cls = 'tag-slight'; tag = winner + ' has slight edge'; }
  else { cls = 'tag-heavy'; tag = winner + ' wins big'; }
  $('vTag').textContent = tag;
  $('vTag').className = 'verdict-tag ' + cls;
}

['A','B'].forEach(side => {
  ['search','org','pos','sort'].forEach(field => {
    const el = $(field+side);
    // v50.20: the text box takes no 'change' listener. 'change' fires on blur, and a click on a result
    // blurs the box first; rebuilding the list at that instant destroyed the node under the pointer and
    // swallowed the click, so every add needed two clicks (two taps on a phone).
    // SA-1: only the text box opens the list on focus. The focus listener used to sit on all four
    // fields, so Tab out of the box -- which the keyboard block closes on -- landed on the sort select
    // and re-opened the list it had just closed, and the list then stayed open while the user worked
    // on the other side. The selects re-render on change, which is the moment they matter.
    if (field === 'search') {
      el.addEventListener('input', () => renderResults(side));
      el.addEventListener('focus', () => renderResults(side));
    } else {
      el.addEventListener('change', () => renderResults(side));
    }
  });
  // SA-8: the placeholder clipped to "Search player or filter, then cli" in a 189px box on a phone
  if (window.innerWidth < 480) $('search'+side).placeholder = 'Search players';
});

