// Use real Roster Level designations from workbook (col l = "MLB" or "AAA")
function isMLBLevel(p) { return p.l === 'MLB'; }
function isAAALevel(p) { return p.l === 'AAA'; }

// Optimized roster: best at C, 1B, 2B, 3B, SS, LF, CF, RF, DH + top 6 SP + top 7 RP = 22 players
function getOptimizedRoster(orgName) {
  const orgPlayers = playersOf(orgName);
  const slots = ['C','1B','2B','3B','SS','LF','CF','RF','DH'];
  const optimized = [];
  const used = new Set();
  // For each position slot, pick the highest-value eligible player not yet used
  slots.forEach(slot => {
    // MGR-3: primary position first, then secondary/tertiary eligibility. gnFieldable30
    // covers by eligibility too; without the fallback an org with nobody whose PRIMARY
    // position is the slot simply left it empty -- Dirty Spikes fielded 21 of 22 with no
    // DH while Bryan Reynolds (RF, eligible RF/LF/DH, 994 RA) sat unused, understating
    // that one manager's bar against the other seven.
    let candidates = orgPlayers.filter(p => p.p === slot && !used.has(p.n));
    if (!candidates.length) {
      candidates = orgPlayers.filter(p => !used.has(p.n) && eligOf(p).includes(slot));
    }
    if (candidates.length > 0) {
      candidates = gnRankBy(candidates, getValue);
      optimized.push(candidates[0]);
      used.add(candidates[0].n);
    }
  });
  // Top 6 SPs
  const sps = gnRankBy(orgPlayers.filter(p => p.p === 'SP' && !used.has(p.n)), getValue).slice(0, 6);
  sps.forEach(p => { optimized.push(p); used.add(p.n); });
  // Top 7 RPs
  const rps = gnRankBy(orgPlayers.filter(p => p.p === 'RP' && !used.has(p.n)), getValue).slice(0, 7);
  rps.forEach(p => { optimized.push(p); used.add(p.n); });
  return optimized;
}

const ELIG = {"Ben Rice":["1B","C","DH"],"Jazz Chisholm Jr.":["2B","3B"],"Kevin McGonigle":["SS","3B"],"JJ Bleday":["CF","LF","RF"],"Jo Adell":["CF","RF"],"Adley Rutschman":["C","DH"],"Vinnie Pasquantino":["1B","DH"],"Peter Lambert":["RP","SP"],"Coby Mayo":["1B","3B"],"Matt McLain":["2B","SS"],"Roman Anthony":["RF","LF","DH"],"Colton Cowser":["CF","LF","RF"],"Max Clark":["CF","DH"],"Tyler Phillips":["RP","SP"],"Ivan Herrera":["C","DH"],"Ezequiel Duran":["SS","1B","2B","3B","LF"],"Daylen Lile":["RF","LF","DH"],"Miguel Vargas":["3B","1B"],"Curtis Mead":["1B","3B"],"Jarren Duran":["LF","CF"],"Salvador Perez":["C","1B","DH"],"Josh Naylor":["1B","DH"],"Zack Gelof":["2B","3B","CF"],"Noelvi Marte":["RF","3B"],"Sam Antonacci":["2B","3B","LF"],"Braden Montgomery":["CF","RF","DH"],"Chase DeLauter":["RF","LF","DH"],"Drake Baldwin":["C","DH"],"Colson Montgomery":["SS","3B"],"Munetaka Murakami":["3B","1B"],"Justin Wrobleski":["RP","SP"],"Hunter Goodman":["C","DH"],"Otto Lopez":["SS","2B"],"Mauricio Dubon":["LF","2B","3B","SS","CF"],"Bryan Reynolds":["RF","LF","DH"],"Andy Pages":["CF","LF","RF"],"Riley Greene":["LF","DH"],"Yoendrys Gomez":["RP","SP"],"Kody Clemens":["1B","2B","LF"],"Lawrence Butler":["RF","CF"],"Spencer Steer":["1B","2B","LF","RF"],"Eugenio Suarez":["3B","DH"],"Jesus Sanchez":["RF","LF"],"George Springer":["DH","RF"],"Angel Martinez":["CF","2B","LF","RF"],"Jack Dreyer":["RP","SP"],"Jose Altuve":["2B","LF","DH"],"Nick Gonzales":["2B","3B"],"Yordan Alvarez":["DH","LF"],"Cody Bellinger":["LF","CF","RF"],"Luis Arraez":["1B","2B","DH"],"Jose Ramirez":["3B","DH"],"Ildemaro Vargas":["2B","1B"],"Mickey Moniak":["RF","LF","CF","DH"],"Joey Cantillo":["RP","SP"],"Daniel Schneemann":["2B","3B","CF"],"Chase Meidroth":["SS","2B"],"Gavin Sheets":["LF","1B","DH"],"Ceddanne Rafaela":["CF","2B"],"Brent Rooker":["DH","RF"],"Tommy Edman":["2B","CF"],"Yainer Diaz":["C","DH"],"Nolan Gorman":["3B","2B","DH"],"Aaron Judge":["RF","DH"],"Ketel Marte":["2B","DH"],"Brooks Lee":["SS","2B","3B"],"Trevor Larnach":["DH","LF","RF"],"Mike Trout":["DH","CF","RF"],"Ryan O'Hearn":["1B","RF","DH"],"Taylor Ward":["LF","DH"],"Teoscar Hernandez":["RF","LF"],"Gary Sanchez":["C","DH"],"Josh Bell":["DH","1B"],"Brett Baty":["3B","1B","2B","RF"],"Josh Smith":["SS","1B","2B","3B"],"Lars Nootbaar":["LF","RF"],"Javier Baez":["SS","3B","CF"],"Kyle Manzardo":["DH","1B"],"Anthony Santander":["DH","RF"],"Luis Rengifo":["3B","2B"],"Liam Hicks":["C","1B","DH"],"Jake Bauers":["1B","LF"],"Chandler Simpson":["CF","LF"],"Shohei Ohtani":["DH","SP"],"Cal Raleigh":["C","DH"],"Brayan Rocchio":["SS","2B"],"Casey Schmitt":["2B","1B","3B","LF","DH"],"TJ Rumfield":["3B","1B","DH"],"Troy Johnston":["RF","1B","LF"],"Brandon Marsh":["CF","LF"],"Carlos Cortes":["RF","DH"],"Ryan Jeffers":["C","DH"],"Luke Raley":["RF","1B"],"Jose Caballero":["RF","2B","3B","SS"],"William Contreras":["C","DH"],"JJ Wetherholt":["SS","2B"],"Tyler Soderstrom":["LF","1B"],"Carson Benge":["CF","LF","RF"],"Juan Soto":["RF","LF","DH"],"James Wood":["LF","RF","DH"],"Jackson Chourio":["CF","LF","RF"],"Samuel Basallo":["C","DH"],"Sal Stewart":["1B","3B"],"Carter Jensen":["C","DH"],"Ernie Clement":["3B","2B","SS"],"Bo Bichette":["SS","3B"],"Colt Emerson":["SS","3B"],"Wyatt Langford":["LF","CF"],"Fernando Tatis Jr.":["RF","2B"],"Shea Langeliers":["C","DH"],"Xavier Edwards":["2B","SS"],"Vladimir Guerrero Jr.":["1B","DH"],"Yandy Diaz":["DH","1B"],"Alec Burleson":["LF","1B","RF","DH"],"Dillon Dingler":["C","DH"],"Rafael Devers":["DH","1B"],"Luis Garcia Jr.":["2B","1B"],"Steven Kwan":["LF","CF"],"Byron Buxton":["CF","DH"],"Seiya Suzuki":["DH","RF"],"Brandon Nimmo":["LF","RF"],"Giancarlo Stanton":["DH","RF"],"Jeff McNeil":["2B","CF"],"Jung Hoo Lee":["CF","RF"]};
const POS_SLOTS=['C','1B','2B','3B','SS','LF','CF','RF','DH'];
function eligOf(p){ const e=ELIG[p.n]; const base=e?e.slice():[]; if(!base.includes(p.p)) base.push(p.p); return base; }
function getKval(p){
  const tj=p.tj||[];
  if(!tj.length) return p.r||0;
  if(tj.length<4) return Math.round(tj.reduce((s,x)=>s+x,0)/tj.length);
  let best=-Infinity;
  for(let i=0;i<=tj.length-4;i++){const w=(tj[i]+tj[i+1]+tj[i+2]+tj[i+3])/4; if(w>best)best=w;}
  return Math.round(best);
}
function getKeeper30(orgName){
  return gnRankBy(playersOf(orgName), getKval).slice(0,30);
}
const ROLE_SLOTS=POS_SLOTS.concat(['SP','RP']);
// Slot eligibility as an 11-bit mask, so the matcher below tests a man against a slot with one
// AND instead of rebuilding eligOf()'s array tens of thousands of times per solve.
function gnSlotMask(p){ const e=eligOf(p); let m=0; for(let i=0;i<ROLE_SLOTS.length;i++){ if(e.includes(ROLE_SLOTS[i])) m|=(1<<i); } return m; }
// Kuhn augmenting paths: how many of ROLE_SLOTS these men can staff one-per-slot, and who ends
// up on each. owner[i] = slot index player i is staffing, or -1.
function gnRoleMatch(mask){
  const owner=new Array(mask.length).fill(-1), seen=new Uint8Array(mask.length);
  let filled=0;
  const tryFill=(s)=>{
    for(let i=0;i<mask.length;i++){
      if(seen[i]||!(mask[i]&(1<<s))) continue;
      seen[i]=1;
      if(owner[i]<0||tryFill(owner[i])){ owner[i]=s; return true; }
    }
    return false;
  };
  for(let s=0;s<ROLE_SLOTS.length;s++){ seen.fill(0); if(tryFill(s)) filled++; }
  return {filled:filled,owner:owner};
}
// MGR-4: best `cap` men by keeper value that still staff every slot this pool can staff at all.
// Deliberately NOT a maximisation: getKeeper30's plain top 30 already IS the maximum of the
// number this sorts by, so a positional constraint can only subtract -- the exact constrained
// optimum for the 2026 league is 237,444 keeper points against the plain top-30's 237,486, and
// ties it in 7 orgs of 8. The old code forced eleven greedy picks (best PRIMARY per slot, then
// SP/RP) before filling to 30, which lost on both counts: it reproduced getKeeper30 exactly for
// 7 of 8 orgs (238 of 240 roster spots identical league-wide), and where it differed it was
// WORSE -- it imported Teoscar Hernandez (Balking Dead, RF, keeper 595, org rank 32) over Dylan
// Lee (RP, keeper 603, rank 30) while five RF-eligible men already sat in the top 30, giving up
// 8 keeper points to cover a slot that was never open; on 11 of 2000 random pools its
// sequential picks also stranded a later slot and left the 30 unfieldable anyway. So do the
// only job there is: seed one witness per staffable slot, fill by keeper value, then trade back
// every witness a better keeper can replace. Measured equal to a min-cost-flow optimum on all 8
// orgs and on 900 random 31-52 man pools; 0.45ms for a full 8-org chart render.
function gnFieldable30(pool,cap){
  const size=cap||30;
  // value each man once and reuse the key for the matcher below: getKval used to run inside the
  // comparator AND again in org.map(getKval) two lines later
  const rows=pool.map(p=>({p:p,k:getKval(p)})); rows.sort((a,b)=>b.k-a.k);
  const org=rows.map(r=>r.p);
  if(org.length<=size) return org;
  const mask=org.map(gnSlotMask), kv=rows.map(r=>r.k);
  const seed=gnRoleMatch(mask), need=seed.filled;
  const inSet=new Uint8Array(org.length); let sel=[];
  seed.owner.forEach((s,i)=>{ if(s>=0){ sel.push(i); inSet[i]=1; } });
  for(let i=0;i<org.length&&sel.length<size;i++){ if(!inSet[i]){ sel.push(i); inSet[i]=1; } }
  const out=[]; for(let i=0;i<org.length;i++){ if(!inSet[i]) out.push(i); }
  for(let pass=0;pass<org.length;pass++){
    sel.sort((a,b)=>kv[a]-kv[b]);                 // cheapest keeper first
    let swapped=false;
    for(let oi=0;oi<out.length&&!swapped;oi++){
      for(let si=0;si<sel.length;si++){
        if(kv[out[oi]]<=kv[sel[si]]) break;       // sel ascending: nothing left for this man to beat
        const trial=sel.slice(), dropped=trial.splice(si,1)[0]; trial.push(out[oi]);
        if(gnRoleMatch(trial.map(i=>mask[i])).filled>=need){
          sel=trial; inSet[dropped]=0; inSet[out[oi]]=1;
          out.splice(oi,1); out.push(dropped); swapped=true; break;
        }
      }
    }
    if(!swapped) break;
  }
  return sel.sort((a,b)=>kv[b]-kv[a]).map(i=>org[i]);
}
function getOptimized30(orgName){
  return gnFieldable30(playersOf(orgName));
}
function passesPosFilter(p) {
  if (!MGR_POS) return true;
  const pos = p.p || '';
  if (MGR_POS === 'OF') return ['LF','CF','RF','OF'].includes(pos);
  if (MGR_POS === 'IF') return ['1B','2B','3B','SS'].includes(pos);
  if (MGR_POS === 'P') return ['SP','RP'].includes(pos);
  return pos === MGR_POS;
}

// CORE-2b: gnROS returns null for the 899 players with no ROS projection, and Math.round(null)
// is 0 -- so the depth chart and the manager bar printed an unprojected man as a confident zero
// and summed him as one. renderVerdict was taught to refuse the same conflation; these surfaces
// were not, which left the page saying "no verdict" in one panel and "0" in the next.
function fmtMgrVal(v){ if(v==null) return 'n/a'; return MODE === 'dollar' ? '$'+v.toFixed(2) : Math.round(v).toLocaleString(); }
function getMgrTooltipEl(){
  let el=document.getElementById('mgrTooltipBox');
  if(!el){ el=document.createElement('div'); el.id='mgrTooltipBox';
    el.style.cssText='position:absolute;pointer-events:none;opacity:0;transition:opacity .08s;z-index:9999;background:rgba(19,39,79,0.97);color:#fff;border:1px solid #BD9B60;border-radius:6px;padding:7px 10px;font:10px/1.45 Lato,Arial,sans-serif;max-height:88vh;box-shadow:0 6px 20px rgba(0,0,0,.4);white-space:nowrap;';
    document.body.appendChild(el); }
  return el;
}
function externalMgrTooltip(context){
  const chart=context.chart, tooltip=context.tooltip, el=getMgrTooltipEl();
  if(tooltip.opacity===0){ el.style.opacity=0; return; }
  const idx=tooltip.dataPoints[0].dataIndex;
  const org=MGR_LABELS[idx]||chart.data.labels[idx];
  const list=MGR_ROSTERS[idx]||[], ct=(MGR_COUNTS[idx]!=null?MGR_COUNTS[idx]:list.length), total=chart.data.datasets[0].data[idx];
  // MC-6: mark the total as a floor when some of the roster carries no projection
  var miss=(MGR_MISSING&&MGR_MISSING[idx])||0;
  let html='<div style="font-weight:700;border-bottom:1px solid #BD9B60;margin-bottom:4px;padding-bottom:3px">'+_iesc(org)+' — '+(miss?'\u2265 ':'')+fmtMgrVal(total)+'  ('+ct+' players'+(miss?', '+miss+' unprojected':'')+')</div>';
  // MC-1: this listed every player. 52 rows fit a desktop and a portrait phone, but the box caps at
  // 88vh and sets pointer-events:none, so on a landscape phone (375px tall) the content ran 414px
  // against a 330px cap and the overflow could not be scrolled to by any means. Show what fits and
  // point the rest at the depth chart, which lists a full roster in a panel that CAN be scrolled.
  var cols=(list.length>26?2:1);
  var ROW=14.5, HEADER=19, FOOTER=19, PAD=14;            // measured, not guessed
  var boxMax=Math.floor(window.innerHeight*0.88);        // the CSS max-height on this box
  var usable=Math.max(ROW*3, boxMax-PAD-HEADER-FOOTER);  // always reserve the overflow line
  var cap=Math.max(6, Math.floor(usable/ROW))*cols;
  var shown=list.slice(0,cap), hidden=list.length-shown.length;
  html+='<div style="columns:'+cols+';column-gap:20px">'+shown.map(function(e,i){return (i+1)+'. '+_iesc(e.n)+' — '+fmtMgrVal(e.v);}).join('<br>')+'</div>';
  if(hidden>0) html+='<div style="margin-top:4px;padding-top:3px;border-top:1px solid #BD9B60;font-style:italic">and '+hidden+' more — open the depth chart for the full roster</div>';
  el.innerHTML=html; el.style.opacity=1;
  const r=chart.canvas.getBoundingClientRect();
  let left=r.left+window.scrollX+tooltip.caretX+14, top=r.top+window.scrollY+12, ew=el.offsetWidth;
  if(left+ew>window.scrollX+window.innerWidth-8) left=r.left+window.scrollX+tooltip.caretX-ew-14;
  const eh=el.offsetHeight, topMin=window.scrollY+8, topMax=window.scrollY+window.innerHeight-eh-8;
  top=Math.max(topMin, Math.min(top, topMax));
  el.style.left=Math.max(8,left)+'px'; el.style.top=top+'px';
}
function rosterForLevel(org){
  const players=playersOf(org);
  if(MGR_LEVEL==='mlb') return players.filter(isMLBLevel);
  if(MGR_LEVEL==='aaa') return players.filter(isAAALevel);
  if(MGR_LEVEL==='optimized') return getOptimizedRoster(org);
  if(MGR_LEVEL==='keeper30') return getKeeper30(org);
  if(MGR_LEVEL==='opt30') return getOptimized30(org);
  return players.slice();   // the index's own array must not leave here
}
const DEPTH_POSITIONS=['C','1B','2B','3B','SS','LF','CF','RF','DH','SP','RP'];
function renderDepth(org){
  DEPTH_ORG=org;
  // MC-4: a bar click and the select both land here, so sync the control in one place
  var _pick=document.getElementById('mgrDepthPick');
  if(_pick && _pick.value!==org) _pick.value=org;
  const roster=rosterForLevel(org);
  const empty=document.getElementById('mgrDepthEmpty'); if(empty) empty.style.display='none';
  const head=document.getElementById('mgrDepthOrg'); if(head) head.textContent='\u2014 '+org+' ('+(LEVEL_LABELS[MGR_LEVEL]||'')+')';
  const grid=document.getElementById('mgrDepthGrid'); if(!grid) return;
  let html='';
  DEPTH_POSITIONS.forEach(function(pos){
    const elig=gnRankBy(roster.filter(function(p){return eligOf(p).includes(pos);}), getValue);
    if(!elig.length) return;
    // sum only what is actually projected; null is absence, not zero (CORE-2b)
    const _seen=elig.map(getValue), _hav=_seen.filter(function(v){return v!=null;});
    const total=_hav.reduce(function(s,v){return s+v;},0);
    const _miss=_seen.length-_hav.length;
    let blk='<div style="border:1px solid #d8cfa8;border-radius:6px;padding:6px 9px;background:#fbf8ef">';
    blk+='<div style="font-weight:700;color:#13274F;border-bottom:1px solid #BD9B60;margin-bottom:4px;padding-bottom:2px;font-size:12.5px">'+pos+' \u2014 '+fmtMgrVal(total)+(_miss?' <span style="font-weight:400;color:#7a6a4a">(+'+_miss+' n/a)</span>':'')+'</div>';
    blk+=elig.map(function(p,i){var sec=(p.p!==pos)?' <span style="color:#CE1141;font-weight:700">*</span>':''; return '<div style="font-size:11px;padding:1px 0">'+(i+1)+' - '+_iesc(p.n)+sec+' - '+fmtMgrVal(getValue(p))+'</div>';}).join('');
    blk+='</div>'; html+=blk;
  });
  grid.innerHTML=html;
}
(function(){ const cv=document.getElementById('mgrChart'); if(cv){ cv.style.cursor='pointer'; cv.addEventListener('click',function(e){ if(!window.chartMgr&&!chartMgr) return; const ch=chartMgr; const els=ch.getElementsAtEventForMode(e,'nearest',{intersect:true},false); if(els.length){ const _org=ch.data.labels[els[0].index]; renderDepth(_org); MGR_EKG_ORG=_org; renderMgrEkg(); } }); } })();
// ====================== MANAGER EKG (value over season) ======================
// Colors for transaction nodes, keyed by node.c
const MGR_EKG_TXN_COLORS = { blue:'#2563eb', red:'#dc2626', purple:'#7c3aed', yellow:'#d4a017', green:'#16a34a' };

// Does player p pass the current #mgrPosFilter for the EKG? (mirrors passesPosFilter)
function gnEkgPassesPos(p){ return passesPosFilter(p); }

// Build the org's relevant teamIds (strings) for the current MGR_LEVEL.
function gnEkgOrgTeams(orgName){
  const o = GNDAILY.orgs[orgName];
  if(!o) return [];
  if(MGR_LEVEL === 'mlb') return [String(o.mlb)];
  if(MGR_LEVEL === 'aaa') return [String(o.aaa)];
  // 'org' uses both squads. optimized / keeper30 / opt30 are computed per-day from that day's roster (see gnEkg* selectors below).
  return [String(o.mlb), String(o.aaa)];
}

// Day-D (1..90) roster for an org via membership: all PLAYERS on either of the org's two squads that day.
function gnEkgDayRoster(orgName, day){
  const o = GNDAILY.orgs[orgName]; if(!o) return [];
  const ids = {}; ids[String(o.mlb)] = 1; ids[String(o.aaa)] = 1;
  const out = [];
  for(const p of PLAYERS){ if(p.eid == null || !GNDAILY.member[String(p.eid)]) continue;
    const tid = gnTeamOnDay(p.eid, day); if(tid && ids[tid]) out.push(p); }
  return out;
}
// Optimized starting lineup of a day-roster, ranked by THAT day's $ (mirrors getOptimizedRoster: best per fielding slot + top 6 SP + top 7 RP).
function gnEkgOptimized(roster, i){
  const slots = ['C','1B','2B','3B','SS','LF','CF','RF','DH'], used = {}, sel = [], val = p => gnDollarOnDay(p, i);
  slots.forEach(s => { const c = gnRankBy(roster.filter(p => p.p === s && !used[p.n]), val); if(c.length){ sel.push(c[0]); used[c[0].n] = 1; } });
  gnRankBy(roster.filter(p => p.p === 'SP' && !used[p.n]), val).slice(0,6).forEach(p => { sel.push(p); used[p.n] = 1; });
  gnRankBy(roster.filter(p => p.p === 'RP' && !used[p.n]), val).slice(0,7).forEach(p => { sel.push(p); used[p.n] = 1; });
  return sel;
}
// 30-man keeper subset of a day-roster: top 30 by long-term keeper value (mirrors getKeeper30 / getKval).
function gnEkgKeeper30(roster){ return gnRankBy(roster, getKval).slice(0,30); }
// 30-man of a day-roster that can still field a lineup, by keeper value (see gnFieldable30).
function gnEkgOpt30(roster){ return gnFieldable30(roster); }

// Tooltip box for EKG transaction nodes (styled like the manager-bar hover).
function getEkgTooltipEl(){
  let el = document.getElementById('mgrEkgTipBox');
  if(!el){ el=document.createElement('div'); el.id='mgrEkgTipBox';
    el.style.cssText='position:absolute;pointer-events:none;opacity:0;transition:opacity .08s;z-index:9999;background:rgba(19,39,79,0.97);color:#fff;border:1px solid #BD9B60;border-radius:6px;padding:7px 10px;font:10px/1.45 Lato,Arial,sans-serif;max-width:280px;box-shadow:0 6px 20px rgba(0,0,0,.4);white-space:normal;';
    document.body.appendChild(el); }
  return el;
}
function externalEkgTooltip(context){
  const chart=context.chart, tooltip=context.tooltip, el=getEkgTooltipEl();
  // only show for the transaction-node dataset (has _txn array)
  const dp = tooltip.dataPoints && tooltip.dataPoints[0];
  const ds = dp && chart.data.datasets[dp.datasetIndex];
  if(tooltip.opacity===0 || !ds || !ds._txn){ el.style.opacity=0; return; }
  const node = ds._txn[dp.dataIndex];
  if(!node){ el.style.opacity=0; return; }
  const g = node.g || 0;
  // MGR-7: node.g is the org-wide swing. When the plotted line is narrower than the org
  // (position filter, or an optimized/30-man level) the two are not comparable, so label it.
  const gStr = (g>=0?'+$':'-$') + Math.abs(g).toFixed(2)
    + (window.__gnEkgNarrowed ? ' org-wide' : '');
  let html='<div style="font-weight:700;border-bottom:1px solid #BD9B60;margin-bottom:4px;padding-bottom:3px">'+_iesc(GNDAILY.dates[node.sp-1])+'  —  <span style="color:'+(g>=0?'#7CFC9A':'#ff9b9b')+'">'+gStr+'</span></div>';
  var _EKGDOT={green:'#16a34a',purple:'#7c3aed',blue:'#2563eb',red:'#dc2626',yellow:'#d4a017'};
  var _parts=(node.parts&&node.parts.length)?node.parts:[{c:node.c,t:node.t,a:node.a,d:node.d,g:node.g}];
  _parts.forEach(function(pt){
    html+='<div style="margin-top:4px"><span style="color:'+(_EKGDOT[pt.c]||'#fff')+';font-weight:700">●</span> '+_iesc(pt.t||'')+'</div>';
    if(pt.a&&pt.a.length) html+='<div style="margin-left:11px"><span style="color:#7CFC9A">In:</span> '+_iesc(pt.a.join(', '))+'</div>';
    if(pt.d&&pt.d.length) html+='<div style="margin-left:11px"><span style="color:#ff9b9b">Out:</span> '+_iesc(pt.d.join(', '))+'</div>';
  });
  el.innerHTML=html; el.style.opacity=1;
  const r=chart.canvas.getBoundingClientRect();
  let left=r.left+window.scrollX+tooltip.caretX+14, top=r.top+window.scrollY+tooltip.caretY-10, ew=el.offsetWidth;
  if(left+ew>window.scrollX+window.innerWidth-8) left=r.left+window.scrollX+tooltip.caretX-ew-14;
  el.style.left=Math.max(8,left)+'px'; el.style.top=Math.max(8,top)+'px';
}

function renderMgrEkg(){
  const wrap = document.getElementById('mgrEkgWrap');
  const cv = document.getElementById('mgrEkgChart');
  if(!wrap || !cv) return;
  if(!MGR_EKG_ORG){ wrap.style.display='none'; if(chartMgrEkg){ chartMgrEkg.destroy(); chartMgrEkg=null; }
    gnDescribeChart('mgrEkgChart', 'Value over season. No manager selected.'); return; }
  wrap.style.display='block';
  const head = document.getElementById('mgrEkgOrg');
  // MGR-2: this line is daily dollars from gnDollarOnDay, which has no slider-aware or
  // ROS-aware form -- so it does not follow the value mode, the RA/Pure blend or the
  // career-years slider that the bar above it does. Say so here rather than leave the
  // reader to assume the two charts share a unit (in the default RA mode they are 527x
  // apart; at 10 career years, 8.6x).
  if(head) head.textContent = '— ' + MGR_EKG_ORG + ' (' + (LEVEL_LABELS[MGR_LEVEL]||'') + ')'
    + (MGR_POS ? ' / ' + MGR_POS : '')
    + ' · daily $ value — not adjusted by the value mode or the sliders';
  const teams = gnEkgOrgTeams(MGR_EKG_ORG);
  const teamSet = {}; teams.forEach(t => teamSet[t]=1);
  const D = GNDAILY.days;
  // EKG line: for each day (1..90) sum daily $ over the manager's roster that day, honoring the level + position filter.
  const line = new Array(D).fill(0);
  const subsetLvl = (MGR_LEVEL === 'optimized' || MGR_LEVEL === 'keeper30' || MGR_LEVEL === 'opt30');
  if(subsetLvl){
    // optimized / 30-man: rebuild the chosen subset from that day's roster, then sum the subset's daily $.
    for(let i=0;i<D;i++){
      const roster = gnEkgDayRoster(MGR_EKG_ORG, i+1);
      let sub;
      if(MGR_LEVEL === 'optimized') sub = gnEkgOptimized(roster, i);
      else if(MGR_LEVEL === 'keeper30') sub = gnEkgKeeper30(roster);
      else sub = gnEkgOpt30(roster);
      for(const p of sub){ if(MGR_POS && !gnEkgPassesPos(p)) continue; line[i] += gnDollarOnDay(p, i); }
    }
  } else {
    // org / mlb / aaa: sum every rostered player on the relevant squad(s) that day.
    for(const p of PLAYERS){
      if(p.eid == null) continue;
      if(!GNDAILY.member[String(p.eid)]) continue;
      if(MGR_POS && !gnEkgPassesPos(p)) continue;
      for(let i=0;i<D;i++){
        const tid = gnTeamOnDay(p.eid, i+1);
        if(tid && teamSet[tid]) line[i] += gnDollarOnDay(p, i);
      }
    }
  }
  // MGR-1: the bar above totals playersOf(org) -- the workbook's org
  // field -- while this line totals whoever GNDAILY.member says was on the squad. They
  // disagree on the final day for players the workbook has moved to FA whose ESPN
  // membership run was never closed with a terminal '.' segment (9 such records on this
  // build). The calculator cannot know WHEN they were actually dropped, so it must not
  // invent a departure date and quietly bend the line. Report the disagreement instead,
  // measured against exactly the selection this line used.
  const _ghosts = (() => {
    const out = [];
    if (subsetLvl) {
      const roster = gnEkgDayRoster(MGR_EKG_ORG, D);
      let sub;
      if (MGR_LEVEL === 'optimized') sub = gnEkgOptimized(roster, D - 1);
      else if (MGR_LEVEL === 'keeper30') sub = gnEkgKeeper30(roster);
      else sub = gnEkgOpt30(roster);
      for (const p of sub) {
        if (MGR_POS && !gnEkgPassesPos(p)) continue;
        if (p.o !== MGR_EKG_ORG) out.push(p);
      }
    } else {
      for (const p of PLAYERS) {
        if (p.eid == null || !GNDAILY.member[String(p.eid)]) continue;
        if (MGR_POS && !gnEkgPassesPos(p)) continue;
        const tid = gnTeamOnDay(p.eid, D);
        if (tid && teamSet[tid] && p.o !== MGR_EKG_ORG) out.push(p);
      }
    }
    return out;
  })();
  (function(){
    var wrap = document.getElementById('mgrEkgWrap');
    if (!wrap) return;
    var el = document.getElementById('mgrEkgRecon');
    if (!el) {
      el = document.createElement('div');
      el.id = 'mgrEkgRecon';
      el.className = 'history-note';
      el.style.margin = '6px 0 0';
      wrap.appendChild(el);
    }
    if (!_ghosts.length) { el.style.display = 'none'; el.textContent = ''; return; }
    var amt = 0;
    for (var i = 0; i < _ghosts.length; i++) amt += gnDollarOnDay(_ghosts[i], D - 1);
    var names = _ghosts.map(function(p){ return p.n + ' (now ' + (p.o || '?') + ')'; }).join(', ');
    el.textContent = 'Reconciliation: this line still counts ' + _ghosts.length + ' player'
      + (_ghosts.length > 1 ? 's' : '') + ' the workbook no longer assigns to ' + MGR_EKG_ORG
      + ' \u2014 ' + names + ' \u2014 worth $' + amt.toFixed(2) + ' on the final day, which is why the'
      + ' right-hand end sits above the bar. Their ESPN membership run was never closed when they were'
      + ' dropped, and the record does not say when that happened, so this is reported rather than guessed.';
    el.style.display = 'block';
  })();
  const labels = GNDAILY.dates.slice();
  // Transaction nodes overlay: x = dates[sp-1], y = line value that day.
  // MGR-7: the dots are org-wide transactions but their y is read off the FILTERED line,
  // so with a position filter active a dot could sit on a series that does not contain any
  // of the players it describes -- and its tooltip could report a gain larger than the whole
  // plotted line. Drop nodes that name nobody passing the current position filter, and mark
  // the remaining gains as org-wide whenever the line is narrower than the org.
  const _txnNames = (n) => {
    const parts = (n.parts && n.parts.length) ? n.parts : [n];
    const out = [];
    parts.forEach(pt => { (pt.a || []).forEach(x => out.push(x)); (pt.d || []).forEach(x => out.push(x)); });
    return out;
  };
  const _byName = {};
  for (const p of PLAYERS) if (p && p.n && _byName[p.n] === undefined) _byName[p.n] = p;
  const nodes = (GNDAILY.txn[MGR_EKG_ORG] || []).filter(n => {
    if (!MGR_POS) return true;
    const names = _txnNames(n);
    if (!names.length) return true;   // nothing named -- keep it rather than hide a real move
    return names.some(nm => { const p = _byName[nm]; return p && gnEkgPassesPos(p); });
  });
  window.__gnEkgNarrowed = !!MGR_POS || subsetLvl;
  const ptData = nodes.map(n => ({ x: GNDAILY.dates[n.sp-1], y: line[n.sp-1] }));
  const ptColors = nodes.map(n => MGR_EKG_TXN_COLORS[n.c] || '#888');
  const lineColor = MGR_COLORS[MGR_EKG_ORG] || '#13274F';
  const config = {
    type: 'line',
    data: { labels, datasets: [
      {
        label: 'Value over season', data: line,
        borderColor: lineColor, backgroundColor: lineColor + '22',
        borderWidth: 2.5, pointRadius: 0, pointHoverRadius: 0, tension: 0.15, fill: true, order: 2
      },
      {
        type: 'scatter', label: 'Transactions',
        data: ptData, _txn: nodes,
        pointBackgroundColor: ptColors, pointBorderColor: '#fff', pointBorderWidth: 1.5,
        pointRadius: 5, pointHoverRadius: 7, showLine: false, order: 1
      }
    ] },
    options: {
      responsive: true, maintainAspectRatio: false,
      interaction: { mode: 'nearest', intersect: true },
      plugins: {
        legend: { display: false },
        tooltip: { enabled: false, external: externalEkgTooltip,
          filter: (item) => item.datasetIndex === 1 }
      },
      scales: {
        y: { ticks: { font: { size: 10 }, callback: (v, i, ticks) => gnAxisTick('$', v, ticks) }, beginAtZero: false, title: { display: true, text: 'Daily $ value', font: { size: 10 } } },
        x: { type: 'category', ticks: { font: { size: 9 }, maxTicksLimit: 12, autoSkip: true } }
      }
    }
  };
  // review: assigning .options on a live chart does not reliably re-resolve plugin blocks. The
  // other four charts rebuild; this was the last one on the old shape.
  if(chartMgrEkg){ chartMgrEkg.destroy(); }
  chartMgrEkg = new Chart(cv.getContext('2d'), config);
}

function renderMgrChart() {
  const ctx = document.getElementById('mgrChart').getContext('2d');
  const totals = MANAGER_ORGS.map(org => {
    const players = playersOf(org);
    let filtered = players;
    if (MGR_LEVEL === 'mlb') filtered = players.filter(isMLBLevel);
    else if (MGR_LEVEL === 'aaa') filtered = players.filter(isAAALevel);
    else if (MGR_LEVEL === 'optimized') filtered = getOptimizedRoster(org);
    else if (MGR_LEVEL === 'keeper30') filtered = getKeeper30(org);
    else if (MGR_LEVEL === 'opt30') filtered = getOptimized30(org);
    filtered = filtered.filter(passesPosFilter);
    // MC-6: the depth chart inside this same card already treats a null as absence rather than zero
    // (CORE-2b). This total added getValue straight into a sum, where null coerces to 0. No rostered
    // player is unprojected on this build, so it never bit -- but the two halves of one card
    // disagreed about what a missing projection means, and only one of them was right.
    const list = filtered.map(p => ({ n: p.n, v: getValue(p) }))
      .sort((a, b) => (b.v == null ? -Infinity : b.v) - (a.v == null ? -Infinity : a.v));
    const have = list.filter(e => e.v != null);
    const total = have.reduce((s, e) => s + e.v, 0);
    return { org, total, count: filtered.length, list, missing: list.length - have.length };
  });
  totals.sort((a, b) => b.total - a.total);
  const labels = totals.map(t => t.org);
  const data = totals.map(t => t.total);
  const counts = totals.map(t => t.count);
  const rosters = totals.map(t => t.list);
  const missing = totals.map(t => t.missing);
  const bgColors = labels.map(o => MGR_COLORS[o]);
  const borderColors = labels.map(o => MGR_BORDER[o] || MGR_COLORS[o]);
  MGR_ROSTERS=rosters; MGR_COUNTS=counts; MGR_LABELS=labels; MGR_DATA=data; MGR_MISSING=missing;

  // MGR-8: this used to declare its own LEVEL_LABELS, shadowing the global one with
  // different wording, so the bar's dataset label and the EKG/depth headers called the
  // same setting two different things. Use the global -- its terms are the ones printed
  // on the buttons the user actually clicked.
  const levelLabel = LEVEL_LABELS[MGR_LEVEL] || 'Full org';
  const posSel = document.getElementById('mgrPosFilter');
  const posLabel = MGR_POS ? ' / ' + posSel.selectedOptions[0].text : '';

  const config = {
    type: 'bar',
    data: { labels, datasets: [{
      label: levelLabel + posLabel,
      data, backgroundColor: bgColors, borderColor: borderColors, borderWidth: 2.5
    }] },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        legend: { display: false },
        // MC-5: enabled:false with an external renderer means Chart.js never draws this tooltip,
        // so the label and afterBody callbacks that used to sit here were unreachable. They also
        // formatted numbers by inlining the mode test while the renderer that does run uses
        // fmtMgrVal -- two formatters for the same figures, one of them free to drift unnoticed.
        // The phone build's dead copy even carried a 15-row cap for narrow screens, so the guard
        // against the overflow MC-1 fixes was sitting in code that could never execute.
        tooltip: { enabled: false, external: externalMgrTooltip }
      },
      scales: {
        y: { ticks: { font: { size: 10 }, callback: fmtYAxis }, beginAtZero: true, title: { display: true, text: MODE === 'dollar' ? 'Total $ value' : (MODE === 'ros' ? 'Projected ROS FP' : 'Total RA'), font: { size: 11 } } },
        x: { ticks: { font: { size: 10 }, maxRotation: 30, minRotation: 0 } }
      }
    }
  };
  const _missTotal = missing.reduce((s, m) => s + m, 0);
  gnDescribeChart('mgrChart', 'Manager comparison, ' + labels.length + ' organizations, ' + levelLabel
    + posLabel + '. ' + labels.map((o, i) => o + ' ' + fmtMgrVal(data[i])).join(', ') + '.'
    + (_missTotal ? ' ' + _missTotal + ' players carry no projection and are left out of the totals.' : ''));
  // MC-7: rebuild, like the other chart cards. Reassigning .options on a live chart does not
  // reliably re-resolve plugin blocks.
  if (chartMgr) { chartMgr.destroy(); }
  chartMgr = new Chart(ctx, config);
  if (DEPTH_ORG) renderDepth(DEPTH_ORG);
}

