// ====================== INJURY RISK CHART ======================
let chartInjuryRisk;

function riskColor(ir) {
  if (ir === 0) return '#7fc97f';                    // green - none
  if (ir >= -0.04) return '#ffeb9c';                 // yellow - low
  if (ir >= -0.09) return '#ffc7ae';                 // orange - moderate
  if (ir >= -0.14) return '#ffafaf';                 // red - high
  return '#d9b3ff';                                  // purple - extreme
}

function riskLabel(ir) {
  if (ir === 0) return 'none';
  if (ir >= -0.04) return 'low';
  if (ir >= -0.09) return 'moderate';
  if (ir >= -0.14) return 'high';
  return 'extreme';
}

function renderInjuryRiskChart() {
  const ctx = document.getElementById('injuryRiskChart').getContext('2d');
  const emptyMsg = document.getElementById('injuryRiskEmpty');
  if (state.A.length === 0 && state.B.length === 0) {
    if (chartInjuryRisk) { chartInjuryRisk.destroy(); chartInjuryRisk = null; }
    gnFitChartWrap('injuryRiskChart', 0);
    gnDescribeChart('injuryRiskChart', 'Injury risk assessment. No players picked yet.');
    gnNoData(emptyMsg);
    return;
  }
  // CHT-3: the gate used to stop at "is anything picked", so one healthy player was enough
  // to hide the message and build a chart whose every dataset is [0, 0]. The legend filter
  // then strips those entries as noise, leaving a blank plot on an axis Chart.js pads out to
  // 0 -> -1.00. 1875 of 2118 players have ir === 0, so this was the common case.
  const _picked = state.A.concat(state.B);
  if (!_picked.some(p => Math.abs(p.ir || 0) > 0)) {
    if (chartInjuryRisk) { chartInjuryRisk.destroy(); chartInjuryRisk = null; }
    gnFitChartWrap('injuryRiskChart', 0);
    gnDescribeChart('injuryRiskChart', 'Injury risk assessment. None of the picked players carries an IL penalty.');
    gnNoData(emptyMsg, _picked.length === 1
      ? _picked[0].n + ' carries no IL penalty \u2014 nothing to chart.'
      : 'None of the ' + _picked.length + ' players picked carries an IL penalty \u2014 nothing to chart.');
    return;
  }
  gnNoDataHide(emptyMsg);

  // IR-2: "Team A" was the last card still using that wording. No count here, unlike the sibling
  // cards: only players carrying a penalty are drawn, so a picked-player count would contradict
  // the number of segments. The counts go in the caption line below instead.
  const labels = ['Side A receives', 'Side B receives'];
  // IR-5: healthy players used to become datasets of [0, 0] -- six of eight on a typical pick --
  // invisible, filtered back out of the legend, and the only reason the tooltip needed a null
  // branch. They are simply not charted now, which is also what the caption under the card says.
  const allPlayers = [];
  state.A.forEach(p => { if (Math.abs(p.ir || 0) > 0) allPlayers.push({ p, side: 'A' }); });
  state.B.forEach(p => { if (Math.abs(p.ir || 0) > 0) allPlayers.push({ p, side: 'B' }); });
  const omitted = _picked.length - allPlayers.length;
  let totA = 0, totB = 0;

  const datasets = allPlayers.map(item => {
    const ir = item.p.ir || 0;
    // Bar value is the ABS of injury risk (negative numbers turned positive for display)
    const val = Math.abs(ir);
    if (item.side === 'A') totA += val; else totB += val;
    const data = item.side === 'A' ? [val, 0] : [0, val];
    return {
      label: item.p.n + ' (' + riskLabel(ir) + ')',
      data,
      backgroundColor: riskColor(ir) + 'dd',
      borderColor: riskColor(ir),
      borderWidth: 1
    };
  });
  // IR-3: the one card in this row that never got the adaptive box. Sixteen charted players left
  // a 73px plot inside the fixed 220px wrap.
  gnFitChartWrap('injuryRiskChart', allPlayers.length);
  gnDescribeChart('injuryRiskChart', 'Injury risk assessment, stacked by player. Side A total '
    + totA.toFixed(2) + ', Side B total ' + totB.toFixed(2) + '. Charting ' + allPlayers.length
    + ' of ' + _picked.length + ' picked players'
    + (omitted ? '; the other ' + omitted + ' carry no IL penalty.' : '.'));

  const config = {
    type: 'bar',
    data: { labels, datasets },
    options: {
      responsive: true, maintainAspectRatio: false,
      plugins: {
        // IR-5: no legend filter is needed now that only players with a penalty become datasets.
        // Keeping the history: CHT-2 was a filter that read `chartInjuryRisk` before the
        // `= new Chart(...)` that assigns it, so on the first render it returned undefined for
        // every item and the legend collapsed to nothing. Not reintroducing that shape.
        legend: { position: 'bottom', labels: { font: { size: 10 }, boxWidth: 12 } },
        // IR-1: the caption defines a five-band scale, but green means "no penalty" and those
        // players are not drawn at all, so green can never appear. Say which picks were left out
        // rather than letting the reader match a legend against a roster and wonder.
        subtitle: omitted
          ? { display: true, color: '#6e6d68', font: { size: 10, style: 'italic' }, padding: { bottom: 4 },
              text: 'Charting ' + allPlayers.length + ' of ' + _picked.length + ' picked players; the other '
                + omitted + (omitted === 1 ? ' carries' : ' carry') + ' no IL penalty' }
          : { display: false },
        tooltip: {
          // IR-6: a label callback returning null is not how Chart.js suppresses a line. It is
          // invisible today only because the resolved interaction mode is "nearest"; forcing every
          // dataset active at one index produced five blank rows out of seven. filter is the
          // documented mechanism and holds under any mode. The zero here is the OTHER side's row.
          filter: (item) => (item.parsed.y || 0) > 0,
          callbacks: {
            label: (ctx) => ctx.dataset.label + ': -' + ctx.parsed.y.toFixed(2)
          }
        }
      },
      scales: {
        x: { stacked: true, ticks: { font: { size: 12 } } },
        y: {
          stacked: true,
          ticks: { font: { size: 10 }, callback: v => (v === 0 ? '0' : '-' + v.toFixed(2)) },
          beginAtZero: true,
          title: { display: true, text: 'Cumulative Hit% deduction (|absolute value|)', font: { size: 10 } }
        }
      }
    }
  };
  // IR-8: reassigning .options on a live chart does not reliably re-resolve plugin blocks, and
  // the subtitle above has to appear and disappear with the picks. Rebuild, like the other cards.
  if (chartInjuryRisk) { chartInjuryRisk.destroy(); }
  chartInjuryRisk = new Chart(ctx, config);
}

function renderAllCharts() {
  if (typeof Chart === 'undefined') return; // Chart.js not loaded yet
  renderPlayerChart();
  renderTeamTotalChart();
  renderStackedBarChart();
  renderMgrChart();
  renderInjuryRiskChart();
  const note = document.getElementById('historyNote');
  const dates = (typeof GN_HISTORY_DATES !== 'undefined' && GN_HISTORY_DATES) || [];
  note.textContent = 'Career view: the engine\u2019s own 10-year trajectory (past years reconstructed on the growth ramp). 2026 view: the daily GNDAILY series through ' + GNDAILY.dates[GNDAILY.dates.length-1] + '. ' + (dates.length ? dates.length + ' value snapshots on file (' + dates[0] + ' \u2192 ' + dates[dates.length-1] + ') are kept for the weekly script and are not charted.' : '');
}


