function gnChartsSoon() { if (_gnChartTimer) clearTimeout(_gnChartTimer); _gnChartTimer = setTimeout(gnChartsNow, 150); }
// SL-3: see the slider handlers -- a moving slider defers the five-chart rebuild to the release
renderVerdict = function() { _origRenderVerdict.apply(this, arguments); if (window.GN_SLIDING) gnChartsSoon(); else gnChartsNow(); };

// ====================== PLAYER INSPECTOR ======================
function growthMultiplier(age, isPitcher) {
  if (isPitcher) {
    if (age <= 19) return 1.35;
    if (age <= 21) return 1.30;
    if (age === 22) return 1.25;
    if (age === 23) return 1.20;
    if (age === 24) return 1.15;
    if (age === 25) return 1.10;
    if (age === 26) return 1.05;
    return 1.00;
  } else {
    if (age <= 19) return 1.30;
    if (age <= 21) return 1.25;
    if (age === 22) return 1.20;
    if (age === 23) return 1.15;
    if (age === 24) return 1.10;
    if (age === 25) return 1.05;
    return 1.00;
  }
}

function scarcityMult(pos) { if (pos === 'C') return 1.15; if (pos === '2B') return 1.15; if (pos === '3B') return 1.15; return 1.00; }

function healthyBase(age, pos) {
  const isPitcher = pos === 'SP' || pos === 'RP';
  if (isPitcher && pos === 'SP') {
    if (age <= 28) return 0.94;
    if (age <= 31) return 0.91;
    if (age <= 34) return 0.88;
    if (age <= 36) return 0.85;
    return 0.82;
  }
  if (pos === 'RP') {
    if (age <= 28) return 0.92;
    if (age <= 31) return 0.91;
    if (age <= 34) return 0.88;
    return 0.85;
  }
  // hitter
  if (age <= 28) return 0.96;
  if (age <= 31) return 0.94;
  if (age <= 34) return 0.92;
  if (age <= 36) return 0.88;
  return 0.85;
}

function fatherTimeCliff(age) {
  // Returns cumulative multiplier from age 38 onward
  if (age < 38) return 1.0;
  let m = 1.0;
  for (let a = 38; a <= age; a++) {
    if (a === 38) m *= 0.85;
    else if (a === 39) m *= 0.80;
    else m *= 0.50;
  }
  return m;
}

// PI-5: list-or-tree reset on every reload while every other display setting persisted.
let INSPECTOR_VIEW='list', INSP_CURRENT=null;
try{ var _iv=localStorage.getItem('gn-trade-inspview'); if(_iv==='tree'||_iv==='list') INSPECTOR_VIEW=_iv; }catch(e){}
function setInspView(v){INSPECTOR_VIEW=v;
  try{ localStorage.setItem('gn-trade-inspview', v); }catch(e){}
  if(INSP_CURRENT) renderInspector(INSP_CURRENT);}
// X-3: escape the full set, not just & and <. Every caller interpolates into innerHTML or
// into an HTML/SVG attribute, and the options ledger is rebuilt weekly from an ESPN feed --
// one transaction string carrying an angle bracket or a quote would break the markup. The
// data has no & or < today, so widening cannot double-escape anything currently shipped.
function _iesc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function _iln(x1,y1,x2,y2){return '<path d="M'+x1+','+y1+' L'+x2+','+y2+'" stroke="#CE1141" stroke-width="1.5" fill="none"/>';}
function _ibx(x,y,w,h,l1,l2,res){
  var fill=res?'#13274F':'#fff', tcol=res?'#fff':'#13274F', sub=res?'#cdd6e6':'#6e6d68';
  var s='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="7" fill="'+fill+'" stroke="#CE1141" stroke-width="'+(res?2.5:1.5)+'"/>';
  var _tr=function(t,fs){ t=String(t); var mx=Math.floor((w-12)/(fs*0.54)); return t.length>mx?t.slice(0,Math.max(1,mx-1))+'\u2026':t; };
  if(l2!=='' && l2!=null){ s+='<text x="'+(x+w/2)+'" y="'+(y+13)+'" font-size="9.5" text-anchor="middle" fill="'+sub+'">'+_iesc(_tr(l1,9.5))+'</text>'+'<text x="'+(x+w/2)+'" y="'+(y+26)+'" font-size="12" font-weight="700" text-anchor="middle" fill="'+tcol+'">'+_iesc(_tr(l2,12))+'</text>'; }
  else { s+='<text x="'+(x+w/2)+'" y="'+(y+h/2+4)+'" font-size="11" text-anchor="middle" fill="'+tcol+'"'+(res?' font-weight="700"':'')+'>'+_iesc(_tr(l1,11))+'</text>'; }
  return s;
}

// ============ Inspector decision spine ============================
// The derivation tree shows how Pure and Hit% are computed ONCE a player is on a branch.
// It never showed WHY he is on that branch, so a classification that had gone stale was
// invisible: a prospect at 155% of his tool ceiling rendered identically to one at 20%.
// This is the ordered gate sequence of methodology 12B, each step with its real inputs,
// and a flag on any test that would flip if it were re-run right now.
function gnFp2025(p){
  var n=String(p.notes||''),m;
  m=n.match(/\b2025\s*[=:]\s*(-?\d+)/); if(m) return Math.max(0,+m[1]);
  m=n.match(/peak\s+(\d+)\(2025\)/);    if(m) return Math.max(0,+m[1]);
  var j=n.match(/career\s+(\d+)\s+FP cumulative/), y=n.match(/ytd=(\d+)/);
  if(j&&y) return Math.max(0,(+j[1])-(+y[1]));
  if(j) return +j[1];
  return 0;
}
function gnSpineRow(n,name,ref,test,out,warn,skip){
  return '<div class="gn-step'+(skip?' gn-skip':'')+'">'
    + '<div class="gn-num">'+n+'</div>'
    + '<div class="gn-nm">'+name+'<i>'+ref+'</i></div>'
    + '<div class="gn-test">'+test+'</div>'
    + '<div class="gn-out">'+out+(warn?'<span class="gn-flag">stale</span>':'')+'</div>'
    + (warn?'<div class="gn-warn">'+warn+'</div>':'')
    + '</div>';
}
function buildDecisionSpine(p,ctx){
 try{
  var e=p.eng||{}, pit=!!ctx.isPitcher, peak=pit?27:26, t=p.t||'?', b=e.b||'—';
  var ef=p.ef||0, tc=e.tc||0, pk=e.pk, banked=ef, rows='', warns=0;

  // --- 1 TIER (methodology 4) -----------------------------------------------
  var mlbTime=(ef>0)||!!p.ph||(t==='T1'||t==='T2'||t==='T3');
  var w1='';
  if(t==='T4'&&ef>0) w1='<b>2026 MLB production on file ('+ef+' FP)</b> — section 4 puts any player with MLB time below peak age at T3, which unfreezes the maturation stage, level proximity and the pace gate.';
  else if(t==='T4'&&(p.a||0)>30) w1='<b>T4 over age 30</b> — section 4 reclassifies to T5 depth.';
  else if(t==='T3'&&(p.a||0)>=peak) w1='<b>At or past peak age ('+p.a+' vs '+peak+')</b> — section 4 graduates him to T1/T2. Deferred league-wide: without a birthdate the engine cannot tell who BEGAN the season at peak from who turned it mid-season.';
  if(w1) warns++;
  rows+=gnSpineRow(1,'Tier','§4','age '+(p.a!=null?p.a:'?')+' vs peak '+peak+' &middot; MLB time '+(mlbTime?'yes':'no'),t,w1,false);

  // --- 2 BASIS (methodology 19.3) -------------------------------------------
  var t2,o2,w2='';
  if(b==='tool'){
    var trig=Math.round(0.70*tc);
    t2='banked '+Math.round(banked)+' vs 70% of tool ceiling ('+trig+')';
    o2='TOOL';
    if(tc&&banked>=trig) w2='<b>Production has passed the trigger ('+Math.round(banked/tc*100)+'% of the ceiling)</b> — section 19.3 replaces the projection with production, retires the scouting bust, and drops the maturation discount.';
  } else if(b==='prod'){
    t2='peak '+(pk!=null?pk:'—')+(e.py?' ('+e.py+')':'')+' &times; growth &times; scarcity'; o2='PRODUCTION';
  } else if(b==='vet'){
    t2='peak '+(pk!=null?pk:'—')+(e.py?' ('+e.py+')':'')+' &times; regression'; o2='VETERAN';
    if(t==='T3') w2='<b>Tier says T3 but the value chain is on the veteran path</b> — peak &times; regression instead of pace &times; growth &times; scarcity.';
  } else if(b==='depth'){ t2='career best '+(e.cb!=null?e.cb:'—')+' &times;1.05'; o2='DEPTH'; }
  else { t2='no basis on file'; o2='—'; }
  if(w2) warns++;
  rows+=gnSpineRow(2,'Basis','§19.3',t2,o2,w2,false);

  // --- 3 PHASE (methodology 12A) --------------------------------------------
  var ORD={'Honeymoon':0,'Book':1,'Established':2};
  if(t==='T3'){
    var lo=pit?250:750===0?0:(pit?250:150), hi=pit?750:500;
    lo=pit?250:150;
    var fp25=(p.fp25!=null?Math.max(0,+p.fp25):gnFp2025(p));   // v50.20: the ESPN fp25 field, notes only as fallback
    var cum=fp25+ef;
    var want=cum>=hi?'Established':(cum>lo?'Book':'Honeymoon');
    var cur=p.ph||'Honeymoon', w3='';
    if(ORD[want]>ORD[cur]) w3='<b>Cumulative production puts him at '+want+'</b> — the section 10 test is promote-only and has to be re-run on every refresh; it has not been.';
    if(w3) warns++;
    rows+=gnSpineRow(3,'Phase','§10','2025 '+Math.round(fp25)+' + 2026 '+Math.round(ef)+' = '+Math.round(cum)+' FP vs '+lo+'/'+hi+' ('+(pit?'pitcher':'hitter')+')',cur,w3,false);
  } else {
    rows+=gnSpineRow(3,'Phase','§12A','applies to T3 only',' — ','',true);
  }

  // --- 4 RATCHET (methodology 19.6) -----------------------------------------
  // 19.6 excludes players already on an alternative current-season treatment.
  var notes=String(p.notes||'');
  var altTreat = /recency floor/i.test(notes) ? 'recency floor §19.5'
               : (/import/i.test(notes)&&(t==='T1')) ? 'import pace §20.15' : '';
  var w4='',o4,t4,skip4=false;
  if(e.rch){ o4='RE-ANCHORED'; t4='peak = banked 2026 to-date '+(pk!=null?pk:'—')+' &middot; banked now '+Math.round(banked)+', no extrapolation';
    if(pk!=null&&banked>pk+0.5){ w4='<b>Banked total ('+Math.round(banked)+') has passed the stored to-date peak ('+pk+')</b> — section 19.6 resets the peak to banked-to-date on every refresh; this record has not been re-anchored since its last ratchet run.'; warns++; } }
  else if(altTreat){ o4='excluded'; t4='on an alternative current-season treatment ('+altTreat+')'; skip4=true; }
  else if(pk!=null&&banked>pk&&banked>0){
    // 19.6 has TWO conditions. (1) banked must pass the prior peak - the floor, so an aged vet
    // never ratchets downward. (2) the new ceiling must BEAT the current pace-adjusted ceiling -
    // the smoothness condition, which makes the crossover continuous. Below it the pace path
    // governs; above it the banked total does.
    var denom4=(pk||0)*((e.b==='vet'&&e.rm)?e.rm:1);
    var ratio4=denom4>0?(banked/denom4):0;
    var pm4=p.pm||1;
    t4='banked '+Math.round(banked)+' vs prior peak '+pk
      +' &middot; re-anchor &times;'+ratio4.toFixed(2)+' vs pace &times;'+pm4;
    if(ratio4>pm4){ o4='not fired';
      w4='<b>Both 19.6 conditions are met</b> — banked has passed the peak AND the re-anchored ceiling (&times;'
        +ratio4.toFixed(2)+') beats the pace-adjusted one (&times;'+pm4
        +'). The peak should re-anchor to banked production and the pace multiplier retire, so the season is not paid twice.';
      warns++; }
    else { o4='below crossover'; }
  }
  else { o4='not fired'; t4='banked '+Math.round(banked)+' vs prior peak '+(pk!=null?pk:'—'); }
  rows+=gnSpineRow(4,'Ratchet','§19.6',t4,o4,w4,skip4);

  // --- 5 PACE (methodology 13, keyed off BASIS) ------------------------------
  var pm=p.pm, want5, why5, ref5='§13';
  if(altTreat==='import pace §20.15'){
    // 20.15 beats 19.6's retirement - an import's Pure is banked, so 2-1/F is the annualisation,
    // not a performance multiplier. It does not beat 13's own closures. The Week 22 run put
    // Okamoto, Imai and Murakami on the import multiplier and left Santa, Ward, Wenninger and
    // Prieto at 1.00 "through the short-circuits"; asking 20.15 first demanded x1.118 of Santa
    // and x1.116 of Ward, both stored at 1.00 and both correct.
    if((p.pc||0)<300){ want5=1.00; why5='zero-prior-peak import, but Pure &lt; 300 &rarr; §13 closes the gate ahead of §20.15'; }
    else {
      var F=(p.ef>0&&p.pace)?(p.pace/p.ef):null;
      want5 = F? Math.round((2-1/F)*1000)/1000 : pm;
      why5='zero-prior-peak import &rarr; time-of-year absorption, pm = 2 &minus; 1/F'+(F?(' (F='+F.toFixed(3)+')'):'');
      ref5='§20.15';
    }
  }
  else if(e.rch){ want5=1.00; why5='ratcheted &rarr; the season is banked in the peak, retired (§19.6)'; }
  else if(/RECENCY FLOOR/.test(notes)){ want5=1.00; why5='recency floor engaged &rarr; pace already banked into Pure, retired (§20.12)'; }
  else if(!gnPmAllowed(p)){ want5=1.00; why5=(t==='T3'?('T3 '+(p.ph||'Honeymoon')+' phase'):(t==='T4'?'T4 tool-grade ceiling':(t==='T5'?'T5 depth ceiling':t)))+' &rarr; a projection, not an established level; gate closed (§13/§20.10)'; }
  else if((p.pc||0)<300){ want5=1.00; why5='Pure &lt; 300, gate closed'; }
  // No pace<=50 and no IL short-circuit below this line, deliberately. Both guarded a COUNTING
  // pace, which missed games mechanically depress - the 13 rule was that a player cannot be
  // charged for a pace he is not permitted to post. v50.22's pm is a rate per appearance, which
  // counts only the appearances he made, and a thin sample is absorbed by the run's own weight w
  // (0.17-0.35 on the low-pace records) instead of by a gate. The Week 22 run says so itself: it
  // wrote a PACE note for 108 players carrying an IL designation and 14 with pace<=50, lifting a
  // stored 1.000 in every one of those cases (prev == 1.000 without exception), and r == pc x pm x h
  // reconciles on the stored multiplier for all of them. Re-deriving the two gates here demanded
  // x1.000 of the 116 that hold a non-1.000 multiplier, 33 of them ABOVE 1.00 (Eovaldi x1.235 on
  // an IL-15) - the retired gate would have taken value off an injured player for out-performing
  // his expected rate.
  else {
    // v50.22: staleness is judged against the note's own post-run figure, which matches the
    // stored pm exactly for every record carrying one. Recomputing the retired counting-stat
    // formula here flagged 650 of 2118 current records as stale.
    var _pn5=gnPaceNote(p);
    // 90 records land here rather than on a gate row now that the two counting-stat gates are
    // gone, and 65 of them have no 2026 production at all - the run never had a rate to compare,
    // which is not the same thing as ALLOW_NEW_PM parking an eligible multiplier.
    if(pm===1.00){ want5=1.00; why5=(!_pn5&&!((p.ef||0)>0))?'no 2026 production on file &rarr; no rate to compare against, held at 1.00':('eligible, parked at 1.00 &rarr; a multiplier is not re-opened mid-season (§13, ALLOW_NEW_PM off)'+((_pn5&&_pn5.calc!=null)?('; the rate basis would give &times;'+_pn5.calc.toFixed(3)):'')); }
    else if(_pn5){ want5=_pn5.pm;
      // Name the short-circuit the rate basis retired, on the row that shows the result: x0.64 on
      // an IL-60 (or x1.25) reads like a bug until you know pm stopped counting missed games.
      var _rt5=!(p.pace>50)?('pace '+p.pace+' no longer retires it &mdash; the thin sample is absorbed by w '+_pn5.w+', not by a gate')
              :(/^(IL-|OUT)/.test(String(p.il||''))?(p.il+' no longer retires it &mdash; a rate per '+_pn5.unit+' counts only the ones he made'):'');
      why5='basis = '+(b==='vet'?'veteran':b)+' &rarr; an established level, gate open &middot; rate basis '+_pn5.rate+' vs '+_pn5.exp+' per '+_pn5.unit+', w '+_pn5.w+', absorption '+GN_ABSORB+' &middot; from the '+_pn5.asOf+' pace run'+(_rt5?(' &middot; '+_rt5):''); }
    else { want5=pm; why5='basis = '+(b==='vet'?'veteran':b)+' &rarr; an established level, gate open &middot; no v50.22 pace run in the audit notes, so the stored multiplier cannot be re-derived here'; }
  }
  var w5='';
  if(pm!=null&&want5!=null&&Math.abs(pm-want5)>0.005)
    { w5='<b>'+(ref5==='§20.15'?'Section 20.15 implies':'The gate implies')+' &times;'+want5.toFixed(3)
          +'</b>, not the stored &times;'+pm+'.'
          +(ref5==='§20.15'?' §13’s closures run ahead of §20.15 above, the precedence the Week 22 run states, so a disagreement here means the stored figure predates a weekly F update — not a section conflict.':'');
      warns++; }
  rows+=gnSpineRow(5,'Pace',ref5,why5,'&times;'+(pm!=null?pm:'—'),w5,false);

  return '<div class="gn-spine"><div class="gn-spine-hd"><b>Decision sequence</b>'
    + '<span>'+(warns?warns+' step'+(warns>1?'s':'')+' would change if re-run now':'all steps current')
    + '</span></div>'+rows+'</div>';
 }catch(err){ return ''; }
}

function buildInspectorTree(p,ctx){
  try{
  var e=p.eng||{}, n=p.notes||'', pc=ctx.pc, pm=ctx.pm, h=p.h, r=ctx.r, base=ctx.base, growth=ctx.growth, scar=ctx.scarcity;
  var rfEng=(e.b==='vet')&&/RECENCY FLOOR v16/.test(n);
  var pure=[];
  var run=null;
  if(e.b==='vet'){
    pure.push([(e.rch?'2026 to-date (ratchet)':'Peak season'),(e.pk!=null?e.pk+' FP':'peak')]); run=(e.pk!=null?e.pk:null);
    if(rfEng&&e.pk!=null){
      var _cl=(e.cl!=null&&e.cl<1)?e.cl:1, _reg=Math.round(e.pk*(e.rm!=null?e.rm:1)*_cl);
      var _A=Math.round((p.pace||0)*0.85), _B=Math.round(e.pk*0.90), _F=Math.min(_A,_B);
      pure.push(['x regr '+(e.rm!=null?e.rm.toFixed(3):'1.000')+(_cl<1?(' x cliff '+_cl.toFixed(2)):''),'= '+_reg]);
      pure.push(['recency: pace '+(p.pace||0)+' x0.85','= '+_A]);
      pure.push(['recency: peak '+e.pk+' x0.90 (cap)','= '+_B]);
      pure.push(['floor = lesser of two','= '+_F]);
      pure.push(['Pure = max(regr '+_reg+', floor '+_F+')','']); run=null;
    } else {
      if(e.rm!=null&&e.rm<1){pure.push(['x regression','x'+e.rm.toFixed(3)]); if(run!=null)run*=e.rm;}
      if(e.cl!=null&&e.cl<1){pure.push(['x Father-Time cliff','x'+e.cl.toFixed(3)]); if(run!=null)run*=e.cl;}
      if(e.sc&&e.sc!==1){pure.push(['x scarcity ('+p.p+')','x'+e.sc.toFixed(2)]); if(run!=null)run*=e.sc;}
    }
  }
  else if(e.b==='prod'){ var _scp=(e.sc!=null?e.sc:scar)||1; var _pb=(e.pk!=null?e.pk:Math.round(pc/((growth||1)*_scp))); pure.push([(e.rch?'2026 to-date (banked)':'Best qualifying season'),''+_pb]); run=_pb; pure.push(['x growth (age '+p.a+')','x'+growth.toFixed(2)]); run*=growth; if(_scp!==1){pure.push(['x scarcity ('+p.p+')','x'+_scp.toFixed(2)]); run*=_scp;} }
  else if(e.b==='tool'){ var _tcv=(e.tc!=null?e.tc:pc); pure.push(['FV'+(e.fv||'?')+' tool ceiling',''+_tcv]); run=_tcv; var _sct=(e.sc!=null?e.sc:scar)||1; if(_sct!==1){pure.push(['x scarcity ('+p.p+')','x'+_sct.toFixed(2)]); run*=_sct;} if(e.bdisc!=null){pure.push(['x SP/RP/Wash '+(e.bw||''),'x'+e.bdisc]); run*=e.bdisc;} }
  else if(e.b==='depth'){ var _cbv=(e.cb!=null?e.cb:pc); pure.push(['Career best',''+_cbv]); run=_cbv; if(e.cb!=null){pure.push(['x1.05 (depth)','x1.05']); run*=1.05;} }
  else { var _bm=n.match(/Pure\s*[\u00d7x]\s*([0-9.]+)/i); var _bwm=n.match(/blend\s+(\d+\/\d+\/\d+)/i); if(_bm){ var _bd=parseFloat(_bm[1]); var _rawc=Math.round(pc/_bd); pure.push(['Raw FV tool ceiling',''+_rawc]); run=_rawc; pure.push(['x SP/RP/Wash '+(_bwm?_bwm[1]:''),'x'+_bd.toFixed(2)+' (bullpen-risk discount, §12.4)']); run*=_bd; } else { pure.push(['Stored prospect ceiling (FV grade)',''+pc]); run=pc; } }
  if(e.matur!=null&&e.matur<1){ pure.push(['x Maturation ('+(e.maturst||'')+')','x'+e.matur.toFixed(2)]); if(run!=null)run*=e.matur; }
  if(!rfEng){
    var _run=null;
    for(var _qi=0;_qi<pure.length;_qi++){ var _v=''+pure[_qi][1]; var _mm=_v.match(/^x(\d*\.?\d+)/); if(_run===null){ var _an=_v.match(/-?\d[\d,]*(\.\d+)?/); if(_an)_run=parseFloat(_an[0].replace(/,/g,'')); } else if(_mm){ _run*=parseFloat(_mm[1]); } }
    if(_run!=null && _run>0 && Math.round(_run)!==pc){ var _resid=pc/_run; var _cz=[]; if(/catcher\s+aging/i.test(n))_cz.push('C-aging'); if(/speed\s+age/i.test(n))_cz.push('speed'); if(/park\s+[A-Z]+:/i.test(n))_cz.push('park'); if(/proximity/i.test(n))_cz.push('proximity'); if(/closer/i.test(n))_cz.push('closer'); var _lbl=_cz.length?(' ('+_cz.join(',')+')'):(Math.abs(_resid-1)>0.01?' (see notes)':' (rounding)'); pure.push(['x adj'+_lbl,'x'+_resid.toFixed(3)]); } }
  pure.push(['= PURE CEILING',''+pc]);
  var hit=[];
  if(e.b==='vet'){ hit.push(['Healthy base (age '+p.a+')',base.toFixed(2)]); if(p.durp)hit.push(['Durability (IL history)','-'+p.durp.toFixed(2)]); if(p.ir)hit.push(['Current IL designation',p.ir.toFixed(2)]); }
  else if(e.b==='prod'){ hit.push(['Healthy base',base.toFixed(2)]); if(p.ph==='Book')hit.push(['x Book phase','x0.85']); else if(p.ph==='Established')hit.push(['x Established','x1.00']); if(p.ir)hit.push(['IL-stack',p.ir.toFixed(2)]); }
  else if(e.b==='tool'){ hit.push(['Healthy base',base.toFixed(2)]); var _mbt=(e.mb!=null?e.mb:(e.bust||0)), _pxt=(e.prox!=null?e.prox:0), _pft=(e.phf!=null?e.phf:1); hit.push(['matrix bust',''+_mbt]); if(_pxt)hit.push(['+ proximity (§11)',(_pxt>0?'+':'')+_pxt]); hit.push(['phase '+(p.ph||'T4')+' x'+_pft,'eff bust '+(Math.round(Math.min(Math.max(0,_mbt+_pxt)*_pft,0.95)*1000)/1000)]); if(/outlier\s+-?\d/.test(n))hit.push(['elite-velo TJ','-0.05']); if(p.ir)hit.push(['IL-stack',p.ir.toFixed(2)]); }
  else { hit.push(['depth default','0.50']); }
  hit.push(['= HIT %',h.toFixed(3)]);
  var pace=[]; pace.push(['2026 pace',''+(p.pace!=null?p.pace:'n/a')]);
  if(Math.abs(pm-1)<1e-9){ var why=(rfEng?'floor banks pace':(e.rch?'banked = peak (ratchet)':(/active IL/i.test(n)?'on IL':(pc<300?'Pure<300':((p.pace||0)<=50?'low pace':'~ expectation'))))); pace.push(['= PACE MULT','1.00 ('+why+')']); }
  else if(/IMPORT-PACE/i.test(n)){ pace.push(['import: banked → annualized','time-of-year absorbed']); pace.push(['= PACE MULT (2-1/F)',pm.toFixed(3)]); }
  else { pace.push(['vs expectation '+Math.round(gnPaceExpectation(p))+' x'+GN_ABSORB,'clamp .5-1.5']); pace.push(['= PACE MULT',pm.toFixed(3)]); }
  var cols=[['PURE',pure],['HIT %',hit],['PACE',pace]];
  var W=720,colW=210,cx=[120,360,600],boxH=30,vg=10,topY=120,hdrY=104;
  var parts=[],edges=[];
  parts.push(_ibx(W/2-135,14,270,34,p.n+' . '+p.p+' . age '+p.a,'',false));
  var typ=(({T1:'T1 peak vet',T2:'T2 past-peak',T3:'T3 young MLB',T4:'T4 prospect',T5:'T5 depth'})[p.t]||p.t)+(e.b==='tool'?' . tool basis':(e.b==='prod'?' . production basis':''))+((p.ph&&p.t==='T3')?' . '+p.ph:'');
  parts.push(_ibx(W/2-165,56,330,26,typ,'',false)); edges.push(_iln(W/2,48,W/2,56));
  var colBottom=[];
  cols.forEach(function(c,ci){
    var x=cx[ci]-colW/2;
    parts.push('<text x="'+cx[ci]+'" y="'+hdrY+'" font-size="10" font-weight="700" text-anchor="middle" fill="#BD9B60">'+_iesc(c[0])+'</text>');
    edges.push(_iln(W/2,82,cx[ci],topY));
    var y=topY,prev=null;
    c[1].forEach(function(nd){ var res=/^=/.test(nd[0]); parts.push(_ibx(x,y,colW,boxH,nd[0],nd[1],res)); if(prev!=null)edges.push(_iln(cx[ci],prev+boxH,cx[ci],y)); prev=y; y+=boxH+vg; });
    colBottom.push([cx[ci],prev+boxH]);
  });
  var maxB=Math.max(colBottom[0][1],colBottom[1][1],colBottom[2][1]); var raY=maxB+34;
  parts.push(_ibx(W/2-115,raY,230,38,'RISK-ADJ = Pure x Pace x Hit%',''+r,true));
  colBottom.forEach(function(o){edges.push(_iln(o[0],o[1],W/2,raY));});
  var dY=raY+60; edges.push(_iln(W/2,raY+38,W/2,dY));
  parts.push('<text x="'+(W/2+72)+'" y="'+(raY+53)+'" font-size="9.5" fill="#6e6d68">/ RAW '+RAW_PER_DOLLAR.toFixed(2)+'</text>');
  parts.push(_ibx(W/2-60,dY,120,40,'$ '+(p.r/RAW_PER_DOLLAR).toFixed(2),'',true));
  var H=dY+56;
  return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto;font-family:Lato,Arial,sans-serif" role="img" aria-label="Value flow tree for '+_iesc(p.n)+'"><rect x="0" y="0" width="'+W+'" height="'+H+'" fill="#FBF8EF"/>'+edges.join('')+parts.join('')+'</svg>';
  }catch(err){ return '<div style="padding:10px;color:#6e6d68;font-size:12px;">Flow tree unavailable for this player.</div>'; }
}
function renderInspector(p) {
  const body = document.getElementById('inspectorBody');
  if (!p) {
    body.innerHTML = '<div class="inspector-empty">Search for any player above to see the exact formula breakdown for their value.</div>';
    return;
  }
  INSP_CURRENT = p;
  const isPitcher = p.p === 'SP' || p.p === 'RP';
  const role = p.p === 'SP' ? 'SP' : (p.p === 'RP' ? 'RP' : 'Hitter');
  const growth = growthMultiplier(p.a, isPitcher);
  const scarcity = scarcityMult(p.p);
  const base = p.base || healthyBase(p.a, p.p);
  const cliff = fatherTimeCliff(p.a);
  const pm = (p.pm == null) ? 1 : p.pm;
  const pc = Math.round(p.pc), r = Math.round(p.r);
  const adjPeak = Math.round(p.pc * pm);
  const _isFA = !!(p.o && p.o.toString().startsWith('FA'));
  const orgBadge = _isFA ? ('Free agent' + (p.o.length > 2 ? ' ' + p.o.toString().slice(2).trim() : '')) : (p.rn ? (p.rn + (p.l ? ' (' + p.l + ')' : '')) : (p.o || '—'));   // v50.20: the FA test comes first (stale rn on dropped players)
  const typeLabels = {'T1':'T1 (Established peak vet)','T2':'T2 (Past-peak vet)','T3':'T3 (Young MLB-tested)','T4':'T4 (Pure prospect)','T5':'T5 (Depth)'};
  const irLabel = !p.ir ? 'none' : (p.ir >= -0.04 ? 'low' : (p.ir >= -0.09 ? 'moderate' : (p.ir >= -0.14 ? 'high' : 'extreme')));
  const sub = (l,v)=>`<div class="formula-row sub"><span class="label">${_iesc(l)}</span><span class="value">${_iesc(v)}</span></div>`;

  // Factor rows that feed the Pure net adjustment (parsed from the audit notes)
  const pureNoteFactors = (() => {
    const n = p.notes || ''; const out = []; let m;
    if ((m=n.match(/park\s+([A-Z]+):\s*([-+]?\d+%)/i))) out.push(sub(`Park factor (${m[1]})`, `${m[2]} to Pure`));
    if ((m=n.match(/catcher\s+aging[^|]*\(([^)]+)\)/i))) out.push(sub('Catcher aging penalty', m[1]));
    if ((m=n.match(/speed\s+age(\d+):\s*(-?\d+)%/i))) out.push(sub(`Speed-dependent aging (age ${m[1]})`, `${m[2]}%`));
    if (/closer\s*\+?20%/i.test(n)) out.push(sub('Closer multiplier (confirmed closer, §12.2)', '×1.20 to Pure'));
    if ((m=n.match(/SP\/RP\/Washout\s+blend\s+(\d+\/\d+\/\d+)[^0-9]*Pure[^0-9]*([0-9.]+)/i))) out.push(sub('SP/RP/Washout blend ('+m[1]+')', '×'+m[2]+' ceiling discount (§12.4)'));
    if ((m=n.match(/Reclassified\s+(T\d(?:-\w+)?)\s*(?:->|→)\s*(T\d)/i))) out.push(sub('Reclassification provenance', m[1]+' → '+m[2]));
    return out.join('');
  })();

  // Type-aware Pure derivation (reconciles to Pure ceiling)
  const sub2 = (l,v,cls) => `<div class="formula-row ${_iesc(cls||'')}"><span class="label">${_iesc(l)}</span><span class="value">${_iesc(v)}</span></div>`;
  const engPure = (() => {
    const e = p.eng; if(!e) return '';
    const pkAgeTxt = isPitcher ? 'peak 27' : 'peak 26';
    const residRow = (run) => {
      if(run==null||run<=0) return '';
      const resid=pc/run; if(Math.abs(resid-1)<=0.01) return '';
      const n=p.notes||''; const cz=[];
      if(/catcher\s+aging/i.test(n))cz.push('catcher aging');
      if(/speed\s+age/i.test(n))cz.push('speed-aging');
      if(/park\s+[A-Z]+:/i.test(n))cz.push('park factor');
      if(/proximity/i.test(n))cz.push('MiLB proximity');
      if(/closer/i.test(n))cz.push('closer role');
      return sub2('× Documented adjustment'+(cz.length?' ('+cz.join(', ')+')':' (see audit notes)'), '×'+resid.toFixed(3), 'sub');
    };
    if (e.b === 'vet') {
      const rfEng = /RECENCY FLOOR v16/.test(p.notes||'');
      let x = sub2(e.rch ? 'Best production — 2026 to-date (in-season ratchet)' : 'Best career season (peak)', `${e.pk} FP (${e.py||'?'})`);
      if (rfEng && e.pk!=null) {
        const _cl=(e.cl!=null&&e.cl<1)?e.cl:1;
        const _reg=Math.round(e.pk*(e.rm!=null?e.rm:1)*_cl);
        const _A=Math.round((p.pace||0)*0.85), _B=Math.round(e.pk*0.90), _F=Math.min(_A,_B);
        x += sub2(`× Age regression (${e.ry||'?'} yr past peak)${_cl<1?` × Father-Time cliff ×${_cl.toFixed(3)}`:''}`, `×${(e.rm!=null?e.rm:1).toFixed(3)} → ${_reg}`, 'sub');
        x += sub2(`Recency floor — 2026 pace ${p.pace} × 0.85`, `= ${_A}`, 'sub');
        x += sub2(`Recency floor — career peak ${e.pk} × 0.90 (sanity cap)`, `= ${_B}`, 'sub');
        x += sub2('Recency floor = lesser of the two', `= ${_F}`, 'sub');
        x += sub2(`= Pure ceiling = greater of (regressed ${_reg}, floor ${_F})`, pc, 'subtotal');
        x += `<div class="formula-row note"><span class="value">Recency floor (§20.12): this still-producing past-peak vet's regressed peak (${_reg}) fell below his demonstrated 2026 production, so Pure is floored to the lesser of 85% of current pace and 90% of career peak. Because current pace is now banked into Pure, the pace multiplier is retired to ×1.00 to avoid paying for it twice.</span></div>`;
        return x;
      }
      let run=(e.pk!=null?e.pk:null);
      if (e.rm < 1){ x += sub2(`× Age regression (${e.ry} yr${e.ry>1?'s':''} past peak; starts age ${e.rs})`, `×${e.rm.toFixed(3)}`); if(run!=null)run*=e.rm; }
      else { x += sub2(`× Age regression (held flat — begins age ${e.rs})`, '×1.000'); }
      if (e.cl < 1){ x += sub2(`× Father Time cliff (age ${p.a})`, `×${e.cl.toFixed(3)}`); if(run!=null)run*=e.cl; }
      if (e.sc && e.sc !== 1){ x += sub2(`× Position scarcity (${p.p}, §5/§15 — applies to vets since June 24)`, `×${e.sc.toFixed(2)}`); if(run!=null)run*=e.sc; }
      if(e.matur!=null&&e.matur<1){ x += sub2('× Maturation ('+(e.maturst||'')+')','×'+e.matur.toFixed(2)+' (unproven prospect, held until MLB-proven)'); if(typeof run!=='undefined'&&run!=null)run*=e.matur; }
      x += residRow(run);
      x += sub2('= Pure ceiling', pc, 'subtotal');
      x += e.rch ? `<div class="formula-row note"><span class="value">In-season ratchet (§19.6): banked 2026 to-date exceeded the pace-adjusted prior-peak ceiling, so to-date is the new peak; regression holds flat this year and resumes in 2027 (pace ×1.00).</span></div>` : `<div class="formula-row note"><span class="value">Vet ceiling = best demonstrated season × age-based regression × Father-Time cliff (§19.2). A new career-best resets the clock.</span></div>`;
      return x;
    }
    if (e.b === 'prod') {
      let x = sub2(e.rch ? 'Best production — 2026 to-date (in-season ratchet)' : 'Best qualifying season (production)', `${e.pk} FP (${e.py||'?'})`);
      let run=(e.pk!=null?e.pk:null);
      x += sub2(`× Growth (age ${p.a}, ${pkAgeTxt})`, (e.g!=null?`×${e.g.toFixed(2)}`:'not stored on this record — folded into the adjustment below')); if(run!=null&&e.g!=null)run*=e.g;
      x += sub2(`× Position scarcity (${p.p})`, (e.sc!=null?`×${e.sc.toFixed(2)}`:'not stored on this record')); if(run!=null&&e.sc!=null)run*=e.sc;
      if(e.matur!=null&&e.matur<1){ x += sub2('× Maturation ('+(e.maturst||'')+')','×'+e.matur.toFixed(2)+' (unproven prospect, held until MLB-proven)'); if(typeof run!=='undefined'&&run!=null)run*=e.matur; }
      x += residRow(run);
      x += sub2('= Pure ceiling', pc, 'subtotal');
      x += e.rch ? `<div class="formula-row note"><span class="value">In-season ratchet (§19.6): banked 2026 to-date passed the pace-adjusted prior-peak ceiling, so to-date is the new peak — growth still applies, the hot-pace multiplier retires (pace ×1.00).</span></div>` : `<div class="formula-row note"><span class="value">Posted a full season ≥70% of the tool grade — production replaces the tool ceiling (§19.3).</span></div>`;
      return x;
    }
    if (e.b === 'tool') {
      let x = sub2(`Tool grade — Future Value ${e.fv}`, `ceiling ${e.tc} FP`);
      let run=(e.tc!=null?e.tc:null);
      x += sub2(`× Position scarcity (${p.p})`, (e.sc!=null?`×${e.sc.toFixed(2)}`:'not stored on this record')); if(run!=null&&e.sc!=null)run*=e.sc;
      if (e.bdisc){ x += sub2(`× SP/RP/Washout blend (${e.bw})`, `×${e.bdisc.toFixed(2)} (bullpen-risk discount)`); if(run!=null)run*=e.bdisc; }
      if(e.matur!=null&&e.matur<1){ x += sub2('× Maturation ('+(e.maturst||'')+')','×'+e.matur.toFixed(2)+' (unproven prospect, held until MLB-proven)'); if(typeof run!=='undefined'&&run!=null)run*=e.matur; }
      x += residRow(run);
      x += sub2('= Pure ceiling', pc, 'subtotal');
      x += `<div class="formula-row note"><span class="value">No qualifying full season — FV tool grade is the ceiling (growth does NOT stack); the SP/RP/Washout blend re-applies where present (§12.4, §19.3).</span></div>`;
      return x;
    }
    if (e.b === 'depth') {
      // INSP-5: this was the only basis that never printed a scarcity row, so for the 38 depth
      // players carrying eng.sc (19 C, 10 3B, 9 2B -- all at 1.15) the stored scarcity fell out
      // inside residRow and was labelled an undocumented adjustment. Two ordering bugs went with
      // it: residRow ran before the maturation row, and maturation was gated on a `run` that this
      // branch never declared, so `typeof run !== 'undefined'` was always false and the displayed
      // multiplier never reached any running total.
      let x = sub2('Career-best (depth / filler)', `${e.cb} FP`);
      let run = (e.cb != null) ? e.cb * 1.05 : null;
      x += sub2('× 1.05 (depth premium)', '×1.05');
      if(e.sc!=null&&e.sc!==1){ x += sub2(`× Position scarcity (${p.p}, §5/§15)`, `×${e.sc.toFixed(2)}`); if(run!=null)run*=e.sc; }
      if(e.matur!=null&&e.matur<1){ x += sub2('× Maturation ('+(e.maturst||'')+')','×'+e.matur.toFixed(2)+' (unproven prospect, held until MLB-proven)'); if(run!=null)run*=e.matur; }
      x += residRow(run);
      x += sub2('= Pure ceiling', pc, 'subtotal');
      return x;
    }
    return '';
  })();
  const engHit = (() => {
    const e = p.eng; if(!e) return '';
    // the depth path does not multiply by the age-based healthy base, so printing it there
    // invited the reader to compute 0.96 x 0.50 = 0.48 against a final Hit% of 0.200.
    let x = (e.b === 'depth') ? '' : sub2(`Healthy base (age ${p.a}, ${role})`, base.toFixed(2));
    if (e.b === 'vet') {
      x += `<div class="formula-row note"><span class="value">Established vet — no scouting bust; Hit% = healthy base, only IL-stack penalties apply.</span></div>`;
    } else if (e.b === 'prod') {
      const phn = p.ph || 'Established';
      x += sub2(`Phase modifier (${phn})`, phn==='Established' ? '×1.00 (proven — bust retired)' : '×0.85 (Book — league adjusts)', 'sub');
    } else if (e.b === 'tool') {
      // v50.20: effective bust = (matrix bust + level proximity) × phase factor — proximity was missing from this chain,
      // so the displayed factors did not multiply to the displayed Hit% for any prospect with a proximity term.
      const _rb = (e.mb != null ? e.mb : (e.bust != null ? e.bust : 0));
      if (e.mb != null) x += sub2('Tool-grade matrix bust (scouting grades)', `${e.mb.toFixed(2)}`, 'sub');
      else x += sub2(`FV-${e.fv} prospect bust`, `${(e.bust||0).toFixed(2)}`, 'sub');
      if (e.surg) x += sub2('TJ / major surgery flag', '+0.25 bust (already in bust above)', 'sub');
      const _px = (e.prox != null ? e.prox : 0);
      if (_px !== 0) x += sub2(`Level proximity (${e.maturst || (p.t==='T3' ? 'MLB' : 'minors')}, §11 — added to the bust)`, `${_px>0?'+':''}${_px.toFixed(2)}`, 'sub');
      const _tb = Math.max(0, _rb + _px);
      const phn = p.ph || '';
      const _pf = (e.phf != null ? e.phf : (phn==='Honeymoon'?0.80:phn==='Book'?1.15:1.00));
      const _be = Math.min(_tb*_pf, 0.95);
      const phdesc = phn==='Honeymoon' ? 'debut optimism — 20% less bust' : phn==='Book' ? 'league has adjusted — 15% more bust' : (phn==='Established' ? 'settled — no bust change' : 'no MLB phase yet (T4) — bust unchanged');
      x += sub2(phn ? `Phase modifier (${phn})` : 'Phase modifier', `bust ${_tb.toFixed(2)} ×${_pf.toFixed(2)} (${phdesc}) → effective bust ${_be.toFixed(3)}`, 'sub');
      x += sub2('Reliability factor', `×${(1-_be).toFixed(3)} (= 1 − effective bust)`, 'sub');
    } else if (e.b === 'depth') {
      // 'flat 0.50' is true only of the 32 depth players who actually carry h = 0.50 (the
      // original Jun-10 reclassification cohort, no eng.rel). The 165 with eng.rel are driven
      // by the small-sample reliability factor and floored at 0.20 -- 171 of 203 were being
      // shown 'flat 0.50' above a final Hit% that said something else.
      if (e.rel != null) {
        const _fl = Math.max(0.20, Math.min(0.96, e.rel));
        x += sub2('Small-sample reliability (limited 2026 record)', `${e.rel.toFixed(2)}`, 'sub');
        if (e.rel < 0.20) x += sub2('Floor at 0.20 (depth minimum)', '→ 0.200', 'sub');
        else if (e.rel > 0.96) x += sub2('Cap at 0.96', '→ 0.960', 'sub');
        if (Math.abs(_fl - (p.h||0)) > 0.005) x += sub2('Further adjustment (see audit notes)', `${_fl.toFixed(3)} → ${(p.h||0).toFixed(3)}`, 'sub');
      } else if (Math.abs((p.h||0) - 0.50) < 0.005) {
        x += sub2('Depth default', 'flat 0.50 Hit% (no scouting profile)', 'sub');
      } else {
        x += sub2('Depth Hit% (hand-set — see audit notes)', `${(p.h||0).toFixed(3)}`, 'sub');
      }
    }
    const _outl=(()=>{const m=(p.notes||'').match(/outlier\s+(-?\d*\.?\d+)/);return m?parseFloat(m[1]):0;})();
    const _pp=(()=>{const m=(p.notes||'').match(/post-peak\s+IL\s+(-?\d*\.?\d+)/);return m?parseFloat(m[1]):0;})();
    if(_outl) x += sub2('Elite-velocity TJ risk (outlier)', `${_outl>0?'+':''}${_outl.toFixed(2)} to Hit% (UCL/Tommy John risk beyond age base)`, 'sub');
    if(_pp) x += sub2('Post-peak IL adjustment', `${_pp>0?'+':''}${_pp.toFixed(2)} to Hit%`, 'sub');
    if (p.durp !== undefined) x += sub2(p.durp ? `Durability — post-peak IL history (${p.durn} stints, ${p.dur60} of them 60-day, over ${(p.durw||0).toFixed(1)}y)${p.dur > p.durp ? ' · raw ' + p.dur.toFixed(2) + ' compressed by the 0.22 soft knee' : ''}` : `Durability — no post-peak IL history (clean over ${(p.durw||0).toFixed(1)}y)`, p.durp ? '-' + p.durp.toFixed(3) : '0.000', 'sub');
    x += sub2(`Current IL designation (${irLabel})`, (p.ir||0).toFixed(2), 'sub');
    const _hc = (p.eng&&p.eng.b==='tool'&&p.ph==='Honeymoon'); const _cl = (_hc&&p.h>=0.85) ? ' — capped at 0.85 (unproven prospect)' : (p.h>=0.96 ? ' — capped at 0.96' : (p.h<=0.20 ? ' — floored at 0.20' : ''));
    x += sub2('= Hit% (final)', `${(p.h*100).toFixed(0)}% (${p.h.toFixed(3)})${_cl}`, 'bold');
    return x;
  })();
  let pureRows = '';
  if (p.eng) { pureRows = engPure; }
  else if (p.t === 'T3' && p.pace) {
    const baseCeil = p.pace * growth * scarcity;
    const netAdj = baseCeil ? (p.pc / baseCeil) : 1;
    pureRows =
      `<div class="formula-row"><span class="label">2026 pace (annualized)</span><span class="value">${p.pace}</span></div>` +
      `<div class="formula-row"><span class="label">× Growth (age ${p.a}, ${isPitcher?'peak 27':'peak 26'})</span><span class="value">×${growth.toFixed(2)}</span></div>` +
      `<div class="formula-row"><span class="label">× Position scarcity (${p.p})</span><span class="value">×${scarcity.toFixed(2)}</span></div>` +
      `<div class="formula-row subtotal"><span class="label">= Base ceiling</span><span class="value">${Math.round(baseCeil)}</span></div>` +
      pureNoteFactors +
      `<div class="formula-row"><span class="label">× Net park / aging / closer / blend adjustment</span><span class="value">×${netAdj.toFixed(3)}</span></div>`;
  } else if (p.t === 'T1' || p.t === 'T2') {
    pureRows =
      `<div class="formula-row note"><span class="value">${p.t} Pure = documented peak-season FPts × age/role regression × position scarcity (× Father Time cliff if age 38+). Peak FPts and the regression curve are baked into the stored Pure; growth multipliers do not apply to established vets.</span></div>` + (scarcity !== 1 ? `<div class="formula-row"><span class="label">× Position scarcity (${p.p})</span><span class="value">×${scarcity.toFixed(2)} (included in stored Pure)</span></div>` : '') +
      (p.a>=38 ? `<div class="formula-row"><span class="label">Father Time cliff (age ${p.a})</span><span class="value">×${cliff.toFixed(3)}</span></div>` : '') +
      pureNoteFactors;
  } else if (p.t === 'T4') {
    const _bm = (p.notes||'').match(/blend\s+(\d+)\/(\d+)\/(\d+)/);
    let _bd = 1, _bw = '';
    if (_bm) { const _a=+_bm[1], _b=+_bm[2], _c=+_bm[3]; _bd = (_a*1.0 + _b*0.60 + _c*0)/100; _bw = `${_a}/${_b}/${_c}`; }
    const _tc = Math.round(pc / scarcity / _bd);
    pureRows =
      `<div class="formula-row"><span class="label">Tool-grade ceiling (scouting matrix)</span><span class="value">${_tc} FP</span></div>` +
      `<div class="formula-row"><span class="label">× Position scarcity (${p.p})</span><span class="value">×${scarcity.toFixed(2)}</span></div>` +
      (_bm ? `<div class="formula-row"><span class="label">× SP/RP/Washout blend (${_bw})</span><span class="value">×${_bd.toFixed(2)} (bullpen-risk discount)</span></div>` : '') +
      pureNoteFactors;
  } else if (p.t === 'T5') {
    pureRows = `<div class="formula-row"><span class="label">Career-best × 1.05 (depth / filler)</span><span class="value">basis</span></div>` + pureNoteFactors;
  }

  // Pace-multiplier rows (reconcile Pure -> pace-adjusted peak)
  const pmRows = (() => {
    const ss=(l,v)=>`<div class="formula-row sub"><span class="label">${l}</span><span class="value">${v}</span></div>`;
    const head=`<div class="formula-row subtotal"><span class="label">= Pure ceiling (healthy peak = expected full-season pace)</span><span class="value">${pc}</span></div>`;
    if (/IMPORT-PACE/i.test(p.notes||'')) { return head + ss('Banked 2026 to-date is the peak (ratchet)', `${pc}`) + ss('Zero prior MLB record — pace activated, time-of-year absorbed', '') + ss('Pace multiplier = 2 − 1/F (rises to 1.00 by season end)', `×${pm.toFixed(3)}`) + `<div class="formula-row bold"><span class="label">= Pace-adjusted value</span><span class="value">${adjPeak}</span></div>`; }
    const _exp = gnPaceExpectation(p), _expR = Math.round(_exp), _preExp = (_expR !== pc);
    if (pm === 1) {
      let why;
      if (p.eng && p.eng.rch) why='retired — banked 2026 to-date is now the peak (§19.6)';
      else if (/RECENCY FLOOR/.test(p.notes||'')) why='retired — the recency floor already banks current pace into Pure (§20.12)';
      else if (p.t==='T5') why='depth tier — the ceiling is career-best, not an established level (§13)';
      else if (p.t==='T4' || (p.eng && p.eng.b==='tool')) why='tool-grade ceiling is a projection, not a level pace can diverge from (§13/§20.10)';
      else if (p.t==='T3' && p.ph!=='Established') why=`${p.ph||'Honeymoon'} phase — held at 1.00 until Established (§20.10)`;
      else if (p.pace==null || p.pace<=0) why='no 2026 pace on file';
      else if (p.pace<=50) why=`2026 pace ${p.pace} ≤ 50 (insufficient sample, short-circuit)`;
      else if (pc<300) why=`expected ceiling ${pc} < 300 (low-ceiling short-circuit)`;
      else if (/^(IL-|OUT)/.test(String(p.il||''))) why=`on the IL (${p.il}) — pace frozen at expected`;
      else { const _pn0 = gnPaceNote(p);
             why = _pn0 && _pn0.calc!=null
               ? `eligible but parked at 1.00 — a multiplier is not re-opened mid-season (§13, ALLOW_NEW_PM off); the rate basis would give ×${_pn0.calc.toFixed(3)}`
               : 'eligible but parked at 1.00 — a multiplier is not re-opened mid-season (§13, ALLOW_NEW_PM off); no v50.22 pace run on this record to re-derive from'; }
      return head + ss('× Pace multiplier', `×1.000 (${why})`);
    }
    // v50.22: pm is rate-vs-rate. Show the chain the engine actually ran (read from this
    // player's pace-run note), never the retired counting-stat formula, and always print the
    // stored pm as the result rather than the value recomputed from the note's rounded rates.
    const _pn = gnPaceNote(p);
    const _tail = `<div class="formula-row"><span class="label">× Pace multiplier (${pm>1?'🔥 hot':'❄️ cold'})</span><span class="value">×${pm.toFixed(3)}</span></div>`
      + `<div class="formula-row bold"><span class="label">= Pace-adjusted peak</span><span class="value">${adjPeak}</span></div>`;
    if (_pn && _pn.ratio!=null) {
      return head
        + ss(`2026 rate (fantasy points per ${_pn.unit})`, `${_pn.rate}`)
        + ss(`Expected rate per ${_pn.unit} at this level`, `${_pn.exp}`)
        + ss('Rate ÷ expected rate', `${_pn.rate} ÷ ${_pn.exp} = ${_pn.ratio.toFixed(3)}`)
        + ss(`× Sample-size weight w = ${_pn.w} (§13) → 1 + w × (ratio − 1)`, `1 + ${_pn.w}×(${_pn.ratio.toFixed(3)} − 1) = ${_pn.inner.toFixed(3)}`)
        + ss(`${Math.round(GN_ABSORB*100)}% time-of-year absorption (${GN_ABSORB_MONTH}, §13)`, `1 + ${GN_ABSORB}×(${_pn.inner.toFixed(3)} − 1) = ${_pn.raw.toFixed(3)}`)
        + (_pn.clamped ? ss('Clamp to [0.50, 1.50]', `→ ${pm.toFixed(3)}`) : '')
        + `<div class="formula-row note"><span class="value">Rate basis (v50.22, GN_PACE_BASIS “rate”), from this player’s ${_pn.asOf} pace run — which moved the multiplier ${_pn.prev.toFixed(3)} → ${_pn.pm.toFixed(3)}. The note rounds both rates to one decimal, so the chain above reproduces the stored multiplier to within ±0.02 (largest gap on this build: 0.017, where the expected rate is small enough that one decimal matters).</span></div>`
        + _tail;
    }
    return head
      + ss('2026 pace (annualized actual)', `${p.pace}`)
      + ss('Derivation', 'not on this record — no v50.22 pace run in the audit notes')
      + _tail;
  })();

  // Hit% modifier rows (parsed from notes) — context for the net adjustment
  const phaseLine = (() => {
    const n = p.notes || '';
    const mtx = n.match(/T3\s+(Honeymoon|Book)\s+matrix\s+bust[=:]?\s*([0-9.]+)/i);
    let val;
    if (p.t === 'T3') {
      const _e = p.eng || {};
      if (_e.b === 'tool') {
        const phn = p.ph || 'Honeymoon';
        const _pf = (_e.phf != null ? _e.phf : (phn==='Honeymoon'?0.80:phn==='Book'?1.15:1.00));
        const _rb = Math.max(0, (_e.mb != null ? _e.mb : (_e.bust != null ? _e.bust : 0)) + (_e.prox != null ? _e.prox : 0)), _be = Math.min(_rb*_pf,0.95);
        const _dir = phn==='Honeymoon' ? '−20% bust (debut optimism)' : phn==='Book' ? '+15% bust (league adjusts)' : 'no change (settled)';
        val = `${phn}: bust+proximity ${_rb.toFixed(2)} ×${_pf.toFixed(2)} = ${_be.toFixed(3)} → reliability ×${(1-_be).toFixed(2)} (${_dir})`;
      } else if (_e.b === 'prod' && p.ph === 'Book') {
        val = `Book ×0.85 on base ${base.toFixed(2)} → ${(base * 0.85).toFixed(2)} (production-basis; bust already 0)`;
      } else if (p.ph === 'Established') {
        val = 'Established — ×1.00 (proven; bust retired)';
      } else { val = '—'; }
    } else if (p.t === 'T1' || p.t === 'T2') {
      val = 'n/a — established vets carry no rookie phase modifier';
    } else if (p.t === 'T4') {
      val = 'n/a — T4 uses the tool-grade bust matrix (below)';
    } else if (p.t === 'T5') {
      val = 'n/a — depth tier';
    } else { val = '—'; }
    const hot = p.t === 'T3' && (p.ph === 'Honeymoon' || p.ph === 'Book');
    return `<div class="formula-row${hot ? ' bold' : ''}"><span class="label">Phase modifier${hot ? ' ('+_iesc(p.ph)+')' : ''}</span><span class="value">${val}</span></div>`;
  })();
  const hitNoteFactors = (() => {
    const n = p.notes || ''; const out = []; let m;
    if ((m=n.match(/T4\s+matrix\s+bust[=:]?\s*([0-9.]+)/i))) out.push(sub('T4 tool-grade bust (matrix)', `${m[1]} → ×${(1-parseFloat(m[1])).toFixed(2)}`));
    if ((m=n.match(/(AAA|AA|A\/?High-?A|Rookie)\s+([-+]?\d+%?)\s+(hitter|pitcher)\s+proximity/i))) out.push(sub(`${m[1]} ${m[3]} proximity`, m[2]));
    if ((m=n.match(/outlier\s+(-?\d*\.?\d+)/i))) out.push(sub('Outlier (elite-velo TJ risk / star cap)', m[1]));
    if ((m=n.match(/post-peak\s+IL\s+(-?\d*\.?\d+)/i))) out.push(sub('Post-peak IL (career injury history)', m[1]));
    if (/T4\s+default/i.test(n)) out.push(sub('Unrated FA / depth default', 'flat 0.50 Hit% (no scouting profile, §2.1)'));
    if (/active\s+IL/i.test(n)) out.push(sub('Active IL status flag', 'currently injured — stack penalty in IL-stack row below'));
    if ((m=n.match(/([^|]*(?:surgery|TJ in stats|Tommy John)[^|]*)/i))) out.push(sub('TJ / major surgery flag', m[1].trim()));
    if ((m=n.match(/two-way[:\s]*([^|]*)/i))) out.push(sub('Two-way bonus (Ohtani special case, §16)', m[1].trim()));
    return out.join('');
  })();
  const hitNet = p.h - base;
  const t4Hit = (() => {
    const n = p.notes || '';
    let x = sub2(`Healthy base (age ${p.a}, ${role})`, base.toFixed(2));
    const mm = n.match(/matrix bust[=:]?\s*([0-9.]+)/i);
    const mb = mm ? parseFloat(mm[1]) : 0;
    const pmx = n.match(/(AAA|AA|A\/?High-?A|Rookie|MLB)\s+([-+]?\d+)%\s+(hitter|pitcher)\s+proximity/i);
    const prox = pmx ? parseFloat(pmx[2])/100 : 0;
    if (mm) x += sub2('Scouting matrix bust (FB / control / out-pitch grades)', `${mb.toFixed(2)}`, 'sub');
    if (pmx) x += sub2(`${pmx[1]} level proximity (${pmx[3]})`, `${prox>=0?'+':''}${prox.toFixed(2)} to bust`, 'sub');
    const bustN = Math.max(mb + prox, 0.10);
    x += sub2('Combined bust (matrix + proximity, floored 0.10)', `${bustN.toFixed(2)} → ×${(1-bustN).toFixed(2)}`, 'sub');
    x += sub2('Base × (1 − combined bust)', (base*(1-bustN)).toFixed(3), 'subtotal');
    const _o=(n.match(/outlier\s+(-?\d*\.?\d+)/)||[])[1]; if(_o) x+=sub2('Elite-velocity TJ risk (outlier)', `${parseFloat(_o)>0?'+':''}${parseFloat(_o).toFixed(2)} to Hit%`, 'sub');
    const _pp=(n.match(/post-peak\s+IL\s+(-?\d*\.?\d+)/)||[])[1]; if(_pp) x+=sub2('Post-peak IL adjustment', `${parseFloat(_pp)>0?'+':''}${parseFloat(_pp).toFixed(2)} to Hit%`, 'sub');
    if (/T4\s+default/i.test(n)) x += sub2('Unrated FA / depth default', 'flat 0.50 Hit% (no scouting profile, §2.1)', 'sub');
    if (p.durp !== undefined) x += sub2(p.durp ? `Durability — post-peak IL history (${p.durn} stints, ${p.dur60} of them 60-day, over ${(p.durw||0).toFixed(1)}y)${p.dur > p.durp ? ' · raw ' + p.dur.toFixed(2) + ' compressed by the 0.22 soft knee' : ''}` : `Durability — no post-peak IL history (clean over ${(p.durw||0).toFixed(1)}y)`, p.durp ? '-' + p.durp.toFixed(3) : '0.000', 'sub');
    x += sub2(`Current IL designation (${irLabel})`, (p.ir||0).toFixed(2), 'sub');
    const _cl = p.h>=0.96?' — capped at 0.96':(p.h<=0.20?' — floored at 0.20':'');
    x += sub2('= Hit% (final)', `${(p.h*100).toFixed(0)}% (${p.h.toFixed(3)})${_cl}`, 'bold');
    x += `<div class="formula-row note"><span class="value">T4 Hit% = clamp( base × (1 − [matrix bust + level proximity]) + outlier + post-peak + IL-stack , 0.20 , 0.96 ).</span></div>`;
    return x;
  })();

  const spineHTML = buildDecisionSpine(p,{isPitcher:isPitcher});
  const treeSVG = buildInspectorTree(p,{base:base,growth:growth,scarcity:scarcity,pm:pm,pc:pc,r:r,isPitcher:isPitcher,role:role});
  body.innerHTML = `
    <div style="display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 12px; flex-wrap: wrap; gap: 12px;">
      <div>
        <div style="font-size: 16px; font-weight: 500;">${_iesc(p.n)}</div>
        <div style="font-size: 12px; color: var(--color-text-secondary, #6e6d68);">${_iesc(p.p)} | age ${p.a} | ${role} | ${_iesc(orgBadge)}</div>
      </div>
      <div style="text-align: right;">
        <div style="font-size: 20px; font-weight: 500;">${r} Peak RA / $${(p.r/RAW_PER_DOLLAR).toFixed(2)}</div>
        <div style="font-size: 12px; color: var(--color-text-secondary, #6e6d68);">Pure: ${pc} | Hit%: ${(p.h*100).toFixed(0)}%</div>
        <!-- PI-6: these figures are the peak-season derivation. They do not move with the value mode
             or the two sliders, which the value-over-time cards now say outright and this one did not. -->
        <div style="font-size: 11px; font-style: italic; color: var(--color-text-tertiary, #9c9b96);">peak-season basis &mdash; not changed by the value mode or the sliders</div>
      </div>
    </div>

    ${spineHTML}
    <div class="toggle" id="inspViewToggle" style="display:inline-flex;margin-bottom:10px;">
      <button type="button" data-insp-view="list" class="${INSPECTOR_VIEW!=='tree'?'active':''}">List view</button>
      <button type="button" data-insp-view="tree" class="${INSPECTOR_VIEW==='tree'?'active':''}">Flow tree</button>
    </div>
    <div id="inspTreeView" style="display:${INSPECTOR_VIEW==='tree'?'block':'none'};margin-bottom:4px;">${treeSVG}</div>

    <div class="player-card" id="inspListView" style="${INSPECTOR_VIEW==='tree'?'display:none;':''}">
      <div class="formula-section">
        <h4>Classification &amp; Inputs</h4>
        <div class="formula-row"><span class="label">Type</span><span class="value">${_iesc(typeLabels[p.t] || p.t)}</span></div>
        <div class="formula-row"><span class="label">Phase</span><span class="value">${_iesc(p.ph || '—')}${p.t==='T3' ? (p.eng && p.eng.b==='tool' ? ' — bust ×'+((p.ph==='Honeymoon')?'0.80':(p.ph==='Book')?'1.15':'1.00') : (p.ph==='Book' ? ' — Hit% ×0.85' : (p.ph==='Established' ? ' — ×1.00' : ''))) : ''}</span></div>
        <div class="formula-row"><span class="label">Position</span><span class="value">${_iesc(p.p)}</span></div>
        <div class="formula-row"><span class="label">Age</span><span class="value">${p.a}</span></div>
        <div class="formula-row"><span class="label">2026 pace (annualized)</span><span class="value">${p.pace != null ? p.pace : 'n/a'}</span></div>
        <div class="formula-row"><span class="label">Confidence</span><span class="value">${_iesc(p.conf || '—')}</span></div>
        <div class="formula-row"><span class="label">Fantasy roster</span><span class="value">${_iesc(orgBadge)}</span></div>
      </div>

      <div class="formula-section">
        <h4>Pure Ceiling Derivation</h4>
        ${pureRows}
        ${pmRows}
      </div>

      <div class="formula-section">
        <h4>Hit% Derivation</h4>
        ${p.eng ? engHit + `<div class="formula-row note"><span class="value">v11 Hit% — vets: healthy base; T3 production-basis: base × phase (Book ×0.85 / Established ×1.00); T3 tool-basis &amp; T4: base × (1 − (matrix bust + level proximity) × phaseFactor), where phase multiplies the BUST (Honeymoon ×0.80, Book ×1.15, Established ×1.00; T4 ×1.00); clamp [0.20, 0.96] (Honeymoon tool cap 0.85).</span></div>` : t4Hit}
      </div>

      <div class="formula-section">
        <h4>Peak Season Value (RA = Pure × Pace mult × Hit%)</h4>
        <div class="formula-row"><span class="label">Pace-adjusted peak</span><span class="value">${adjPeak}</span></div>
        <div class="formula-row"><span class="label">× Hit% (final)</span><span class="value">×${p.h.toFixed(3)}</span></div>
        <div class="formula-row bold"><span class="label">= Peak RA (ceiling)</span><span class="value">${r}</span></div>
        <div class="formula-row"><span class="label">$ Value = RA ÷ ${RAW_PER_DOLLAR.toFixed(2)}</span><span class="value">$${(p.r/RAW_PER_DOLLAR).toFixed(2)}</span></div>
        <div class="formula-row note"><span class="value">Identity check: ${pc} × ${pm.toFixed(3)} × ${p.h.toFixed(3)} = ${Math.round(p.pc*pm*p.h)} RA. Peak season = age 26 (hitters) / 27 (pitchers).</span></div>
      </div>

      <div class="formula-section" style="grid-column: 1 / -1;">
        <h4>10-Year Trajectory (year-by-year ${FADE_MODE==='on' && (p.t==='T3'||p.t==='T4') ? 'RA — bust-risk-off view: bust, SP/RP-blend &amp; maturation hold all phasing out' : 'RA, ramping toward peak then regressing'})</h4>
        <div class="traj-grid">
          ${(p.tj || []).map((v, i) => { const vv = fadeAdjustedTj(p, i); return `<div style="text-align: center; padding: 4px; background: ${i === 0 ? '#fff8e1' : '#fff'}; border-radius: 4px; ${i === 0 ? 'border: 1px solid #f0c674;' : ''}"><div style="color: #6e6d68;">${i === 0 ? 'Current' : 'Y'+(i+1)}</div><div style="font-weight: 500;">${Math.round(vv)}</div></div>`; }).join('')}
        </div>
      </div>

      <div class="formula-section" style="grid-column: 1 / -1;">
        <h4>Notes &amp; Audit Trail</h4>
        <div class="formula-notes">${_iesc(p.notes || '(no notes)')}</div>
      </div>
    </div>
  `;
}


const inspectorSearch = document.getElementById('inspectorSearch');
const inspectorResults = document.getElementById('inspectorResults');

const INSP_CAP = 30;
inspectorSearch.addEventListener('input', () => {
  const q = gnFold(inspectorSearch.value.trim());
  // PI-7b: the side pickers answer from the first keystroke; this box ignored one-character queries.
  if (!q) {
    inspectorResults.classList.remove('open');
    inspectorResults.innerHTML = '';
    return;
  }
  // PI-2: one substring test meant "rodriguez julio" found nobody here while the side pickers found
  // him. Every typed word has to appear in the folded name, in any order -- the same rule they use.
  const qTokens = q.split(' ').filter(Boolean);
  const all = PLAYERS.filter(p => { const fn = gnFold(p.n); return qTokens.every(t => fn.indexOf(t) !== -1); });
  const total = all.length;
  const matches = all.slice(0, INSP_CAP);
  if (matches.length === 0) {
    inspectorResults.innerHTML = '<div class="inspector-result" style="color:#9c9b96;">No matches</div>';
  } else {
    inspectorResults.innerHTML = matches.map((p, i) =>
      `<div class="inspector-result" data-idx="${i}" data-n="${_iesc(p.n)}" data-o="${_iesc(p.o)}">${_iesc(p.n)} <span style="color:#6e6d68; font-size:11px;">(${_iesc(p.p)}, age ${p.a}, ${_iesc(p.t)}, ${_iesc(rosterBadge(p))})</span></div>`
    ).join('');
    // PI-1: "an" matches 626 players and thirty were shown with nothing saying so. The side pickers
    // carry this note already; the row has no data-n so it stays out of the click and ARIA wiring.
    if (total > matches.length) {
      inspectorResults.insertAdjacentHTML('afterbegin',
        '<div class="inspector-result" style="color:#9c9b96;cursor:default;">Top ' + matches.length
        + ' of ' + total.toLocaleString() + ' matches \u00b7 narrow the search to see the rest</div>');
    }
  }
  inspectorResults.classList.add('open');
  [...inspectorResults.querySelectorAll('.inspector-result[data-n]')].forEach(el => {
    el.addEventListener('click', () => {
      const player = PLAYERS.find(x => x.n === el.dataset.n && x.o === el.dataset.o);
      if (player) {
        renderInspector(player);
        inspectorSearch.value = player.n;
        inspectorResults.classList.remove('open');
        // PI-4: picking a player replaces the whole panel silently. Announce the change through the
        // shared status region -- marking #inspectorBody itself live would read out the entire
        // 377-line breakdown on every render.
        if (typeof gnAnnounce === 'function') gnAnnounce(player.n + ' formula breakdown shown.');
      }
    });
  });
});

// PI-7c: the view buttons are rebuilt inside renderInspector's template on every render, which is
// why they carried inline onclick attributes -- the only ones on the page. One delegated listener on
// the container survives every rebuild and needs no attributes.
document.getElementById('inspectorBody').addEventListener('click', (e) => {
  const b = e.target.closest('[data-insp-view]');
  if (b) setInspView(b.getAttribute('data-insp-view'));
});
inspectorSearch.addEventListener('focus', () => {
  // same stale-cache shape as the Options search: the row click sets .value and clears
  // only the 'open' class, so refocusing revealed the previous query's rows.
  if (inspectorSearch.value.trim().length >= 1) {
    inspectorSearch.dispatchEvent(new Event('input'));
  }
});

